use crate::help;
use std::process::exit;

#[derive(Clone, Debug)]
pub struct Args {
    pub paths: Vec<String>,
    pub depth: Option<u64>,
    pub threads: Option<u64>,
    pub config: Option<String>,
    pub number_of_lines: Option<u64>,
    pub full_paths: bool,
    pub ignore_dirs: Vec<String>,
    pub ignore_all_in_file: Option<String>,
    pub dereference_links: bool,
    pub limit_filesystem: bool,
    pub apparent_size: bool,
    pub reverse: bool,
    pub no_colors: bool,
    pub force_colors: bool,
    pub no_percent_bars: bool,
    pub bars_on_right: bool,
    pub min_size: Option<String>,
    pub screen_reader: bool,
    pub skip_total: bool,
    pub filecount: bool,
    pub ignore_hidden: bool,
    pub invert_filter: Vec<String>,
    pub filter: Vec<String>,
    pub file_types: bool,
    pub terminal_width: Option<u64>,
    pub no_progress: bool,
    pub print_errors: bool,
    pub only_dir: bool,
    pub only_file: bool,
    pub output_format: Option<String>,
    pub stack_size: Option<u64>,
    pub output_json: bool,
    pub mtime: Option<String>,
    pub atime: Option<String>,
    pub ctime: Option<String>,
    pub files0_from: Option<String>,
    pub files_from: Option<String>,
    pub collapse: Vec<String>,
    pub filetime: Option<String>,
}

impl Args {
    pub fn new() -> Self {
        Args {
            paths: vec![],
            depth: None,
            threads: None,
            config: None,
            number_of_lines: None,
            full_paths: false,
            ignore_dirs: vec![],
            ignore_all_in_file: None,
            dereference_links: false,
            limit_filesystem: false,
            apparent_size: false,
            reverse: false,
            no_colors: false,
            force_colors: false,
            no_percent_bars: false,
            bars_on_right: false,
            min_size: None,
            screen_reader: false,
            skip_total: false,
            filecount: false,
            ignore_hidden: false,
            invert_filter: vec![],
            filter: vec![],
            file_types: false,
            terminal_width: None,
            no_progress: false,
            print_errors: false,
            only_dir: false,
            only_file: false,
            output_format: None,
            stack_size: None,
            output_json: false,
            mtime: None,
            atime: None,
            ctime: None,
            files0_from: None,
            files_from: None,
            collapse: vec![],
            filetime: None,
        }
    }
}

fn die_arg(msg: String) -> ! {
    eprintln!("error: {}", msg);
    eprintln!();
    eprintln!("For more information, try '--help'.");
    exit(2);
}

fn needs_value(name: &str, short: Option<char>, kind: &str) -> ! {
    let n = match short {
        Some(c) => format!("-{}, --{} <{}>", c, name.replace('_', "-"), kind),
        None => format!("--{} <{}>", name.replace('_', "-"), kind),
    };
    let _ = n;
    let formatted = format_arg_display(name, short, kind);
    die_arg(format!(
        "a value is required for '{}' but none was supplied",
        formatted
    ))
}

fn format_arg_display(name: &str, short: Option<char>, kind: &str) -> String {
    match short {
        Some(c) => format!("-{}, --{} <{}>", c, name, kind),
        None => format!("--{} <{}>", name, kind),
    }
}

fn parse_uint(s: &str, name: &str, short: Option<char>, kind: &str) -> u64 {
    match s.parse::<u64>() {
        Ok(v) => v,
        Err(e) => {
            let display = format_arg_display(name, short, kind);
            die_arg(format!("invalid value '{}' for '{}': {}", s, display, e))
        }
    }
}

fn valid_output_format(s: &str) -> bool {
    matches!(s, "si" | "b" | "k" | "m" | "g" | "t" | "kb" | "mb" | "gb" | "tb")
}

fn valid_filetime(s: &str) -> bool {
    matches!(s, "a" | "c" | "m")
}

pub fn parse_args() -> Args {
    let raw: Vec<String> = std::env::args().skip(1).collect();
    parse_args_from(&raw, true)
}

pub fn parse_args_from(raw: &[String], allow_help_version: bool) -> Args {
    let mut args = Args::new();
    let mut i = 0;
    let mut positional_only = false;

    // First check for -h/-V with highest priority (they can be combined with others)
    if allow_help_version {
        for a in raw {
            if a == "--help" {
                print!("{}", help::LONG_HELP);
                exit(0);
            }
            if a == "-h" {
                print!("{}", help::SHORT_HELP);
                exit(0);
            }
        }
        for a in raw {
            if a == "-V" || a == "--version" {
                println!("{}", help::VERSION);
                exit(0);
            }
        }
    }

    while i < raw.len() {
        let arg = &raw[i];
        if positional_only {
            args.paths.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            positional_only = true;
            i += 1;
            continue;
        }

        // Helper: take next value
        let mut take_value_long = |long: &str, kind: &str| -> String {
            let name = long.trim_start_matches("--").to_string();
            let short = short_for_long(&name);
            if let Some(eq) = arg.find('=') {
                return arg[eq + 1..].to_string();
            }
            i += 1;
            if i >= raw.len() {
                needs_value(&name, short, kind)
            }
            raw[i].clone()
        };
        let _ = &mut take_value_long;

        // Recognize options
        if arg.starts_with("--") {
            // Long option
            let (name_part, value_part) = match arg.find('=') {
                Some(eq) => (&arg[2..eq], Some(arg[eq + 1..].to_string())),
                None => (&arg[2..], None),
            };
            match name_part {
                "depth" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "depth", Some('d'), "DEPTH");
                    args.depth = Some(parse_uint(&v, "depth", Some('d'), "DEPTH"));
                }
                "threads" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "threads", Some('T'), "THREADS");
                    args.threads = Some(parse_uint(&v, "threads", Some('T'), "THREADS"));
                }
                "config" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "config", None, "FILE");
                    args.config = Some(v);
                }
                "number-of-lines" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "number-of-lines", Some('n'), "NUMBER");
                    args.number_of_lines = Some(parse_uint(&v, "number-of-lines", Some('n'), "NUMBER"));
                }
                "full-paths" => { args.full_paths = true; no_value_allowed(value_part, "full-paths"); }
                "ignore-directory" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "ignore-directory", Some('X'), "PATH");
                    args.ignore_dirs.push(v);
                }
                "ignore-all-in-file" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "ignore-all-in-file", Some('I'), "FILE");
                    args.ignore_all_in_file = Some(v);
                }
                "dereference-links" => { args.dereference_links = true; no_value_allowed(value_part, "dereference-links"); }
                "limit-filesystem" => { args.limit_filesystem = true; no_value_allowed(value_part, "limit-filesystem"); }
                "apparent-size" => { args.apparent_size = true; no_value_allowed(value_part, "apparent-size"); }
                "reverse" => { args.reverse = true; no_value_allowed(value_part, "reverse"); }
                "no-colors" => { args.no_colors = true; no_value_allowed(value_part, "no-colors"); }
                "force-colors" => { args.force_colors = true; no_value_allowed(value_part, "force-colors"); }
                "no-percent-bars" => { args.no_percent_bars = true; no_value_allowed(value_part, "no-percent-bars"); }
                "bars-on-right" => { args.bars_on_right = true; no_value_allowed(value_part, "bars-on-right"); }
                "min-size" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "min-size", Some('z'), "MIN_SIZE");
                    args.min_size = Some(v);
                }
                "screen-reader" => { args.screen_reader = true; no_value_allowed(value_part, "screen-reader"); }
                "skip-total" => { args.skip_total = true; no_value_allowed(value_part, "skip-total"); }
                "filecount" => { args.filecount = true; no_value_allowed(value_part, "filecount"); }
                "ignore-hidden" => { args.ignore_hidden = true; no_value_allowed(value_part, "ignore-hidden"); }
                "invert-filter" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "invert-filter", Some('v'), "REGEX");
                    args.invert_filter.push(v);
                }
                "filter" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "filter", Some('e'), "REGEX");
                    args.filter.push(v);
                }
                "file-types" => { args.file_types = true; no_value_allowed(value_part, "file-types"); }
                "terminal-width" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "terminal-width", Some('w'), "WIDTH");
                    args.terminal_width = Some(parse_uint(&v, "terminal-width", Some('w'), "WIDTH"));
                }
                "no-progress" => { args.no_progress = true; no_value_allowed(value_part, "no-progress"); }
                "print-errors" => { args.print_errors = true; no_value_allowed(value_part, "print-errors"); }
                "only-dir" => { args.only_dir = true; no_value_allowed(value_part, "only-dir"); }
                "only-file" => { args.only_file = true; no_value_allowed(value_part, "only-file"); }
                "output-format" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "output-format", Some('o'), "FORMAT");
                    if !valid_output_format(&v) {
                        die_arg(format!(
                            "invalid value '{}' for '--output-format <FORMAT>'\n  [possible values: si, b, k, m, g, t, kb, mb, gb, tb]",
                            v
                        ));
                    }
                    args.output_format = Some(v);
                }
                "stack-size" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "stack-size", Some('S'), "STACK_SIZE");
                    args.stack_size = Some(parse_uint(&v, "stack-size", Some('S'), "STACK_SIZE"));
                }
                "output-json" => { args.output_json = true; no_value_allowed(value_part, "output-json"); }
                "mtime" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "mtime", Some('M'), "MTIME");
                    args.mtime = Some(v);
                }
                "atime" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "atime", Some('A'), "ATIME");
                    args.atime = Some(v);
                }
                "ctime" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "ctime", Some('y'), "CTIME");
                    args.ctime = Some(v);
                }
                "files0-from" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "files0-from", None, "FILES0_FROM");
                    args.files0_from = Some(v);
                }
                "files-from" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "files-from", None, "FILES_FROM");
                    args.files_from = Some(v);
                }
                "collapse" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "collapse", None, "COLLAPSE");
                    args.collapse.push(v);
                }
                "filetime" => {
                    let v = get_value_from(&arg, value_part, raw, &mut i, "filetime", Some('m'), "FILETIME");
                    if !valid_filetime(&v) {
                        die_arg(format!(
                            "invalid value '{}' for '-m, --filetime <FILETIME>'\n  [possible values: a, c, m]",
                            v
                        ));
                    }
                    args.filetime = Some(v);
                }
                _ => {
                    die_arg(format!(
                        "unexpected argument '--{}' found\n\nUsage: executable [OPTIONS] [PATH]...",
                        name_part
                    ));
                }
            }
            i += 1;
            continue;
        }

        if arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            // Short option(s) possibly combined
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                let rest: String = chars[k + 1..].iter().collect();
                let get_arg_val = |rest: &str, raw: &[String], i: &mut usize, name: &'static str, short: char, kind: &'static str| -> String {
                    if !rest.is_empty() {
                        return rest.to_string();
                    }
                    *i += 1;
                    if *i >= raw.len() {
                        needs_value(name, Some(short), kind)
                    }
                    raw[*i].clone()
                };
                match c {
                    'd' => {
                        let v = get_arg_val(&rest, raw, &mut i, "depth", 'd', "DEPTH");
                        args.depth = Some(parse_uint(&v, "depth", Some('d'), "DEPTH"));
                        break;
                    }
                    'T' => {
                        let v = get_arg_val(&rest, raw, &mut i, "threads", 'T', "THREADS");
                        args.threads = Some(parse_uint(&v, "threads", Some('T'), "THREADS"));
                        break;
                    }
                    'n' => {
                        let v = get_arg_val(&rest, raw, &mut i, "number-of-lines", 'n', "NUMBER");
                        args.number_of_lines = Some(parse_uint(&v, "number-of-lines", Some('n'), "NUMBER"));
                        break;
                    }
                    'p' => { args.full_paths = true; k += 1; }
                    'X' => {
                        let v = get_arg_val(&rest, raw, &mut i, "ignore-directory", 'X', "PATH");
                        args.ignore_dirs.push(v);
                        break;
                    }
                    'I' => {
                        let v = get_arg_val(&rest, raw, &mut i, "ignore-all-in-file", 'I', "FILE");
                        args.ignore_all_in_file = Some(v);
                        break;
                    }
                    'L' => { args.dereference_links = true; k += 1; }
                    'x' => { args.limit_filesystem = true; k += 1; }
                    's' => { args.apparent_size = true; k += 1; }
                    'r' => { args.reverse = true; k += 1; }
                    'c' => { args.no_colors = true; k += 1; }
                    'C' => { args.force_colors = true; k += 1; }
                    'b' => { args.no_percent_bars = true; k += 1; }
                    'B' => { args.bars_on_right = true; k += 1; }
                    'z' => {
                        let v = get_arg_val(&rest, raw, &mut i, "min-size", 'z', "MIN_SIZE");
                        args.min_size = Some(v);
                        break;
                    }
                    'R' => { args.screen_reader = true; k += 1; }
                    'f' => { args.filecount = true; k += 1; }
                    'i' => { args.ignore_hidden = true; k += 1; }
                    'v' => {
                        let v = get_arg_val(&rest, raw, &mut i, "invert-filter", 'v', "REGEX");
                        args.invert_filter.push(v);
                        break;
                    }
                    'e' => {
                        let v = get_arg_val(&rest, raw, &mut i, "filter", 'e', "REGEX");
                        args.filter.push(v);
                        break;
                    }
                    't' => { args.file_types = true; k += 1; }
                    'w' => {
                        let v = get_arg_val(&rest, raw, &mut i, "terminal-width", 'w', "WIDTH");
                        args.terminal_width = Some(parse_uint(&v, "terminal-width", Some('w'), "WIDTH"));
                        break;
                    }
                    'P' => { args.no_progress = true; k += 1; }
                    'D' => { args.only_dir = true; k += 1; }
                    'F' => { args.only_file = true; k += 1; }
                    'o' => {
                        let v = get_arg_val(&rest, raw, &mut i, "output-format", 'o', "FORMAT");
                        if !valid_output_format(&v) {
                            die_arg(format!(
                                "invalid value '{}' for '--output-format <FORMAT>'\n  [possible values: si, b, k, m, g, t, kb, mb, gb, tb]",
                                v
                            ));
                        }
                        args.output_format = Some(v);
                        break;
                    }
                    'S' => {
                        let v = get_arg_val(&rest, raw, &mut i, "stack-size", 'S', "STACK_SIZE");
                        args.stack_size = Some(parse_uint(&v, "stack-size", Some('S'), "STACK_SIZE"));
                        break;
                    }
                    'j' => { args.output_json = true; k += 1; }
                    'M' => {
                        let v = get_arg_val(&rest, raw, &mut i, "mtime", 'M', "MTIME");
                        args.mtime = Some(v);
                        break;
                    }
                    'A' => {
                        let v = get_arg_val(&rest, raw, &mut i, "atime", 'A', "ATIME");
                        args.atime = Some(v);
                        break;
                    }
                    'y' => {
                        let v = get_arg_val(&rest, raw, &mut i, "ctime", 'y', "CTIME");
                        args.ctime = Some(v);
                        break;
                    }
                    'm' => {
                        let v = get_arg_val(&rest, raw, &mut i, "filetime", 'm', "FILETIME");
                        if !valid_filetime(&v) {
                            die_arg(format!(
                                "invalid value '{}' for '-m, --filetime <FILETIME>'\n  [possible values: a, c, m]",
                                v
                            ));
                        }
                        args.filetime = Some(v);
                        break;
                    }
                    _ => {
                        die_arg(format!(
                            "unexpected argument '-{}' found\n\nUsage: executable [OPTIONS] [PATH]...",
                            c
                        ));
                    }
                }
            }
            i += 1;
            continue;
        }

        // Positional
        args.paths.push(arg.clone());
        i += 1;
    }

    args
}

fn short_for_long(name: &str) -> Option<char> {
    match name {
        "depth" => Some('d'),
        "threads" => Some('T'),
        "number-of-lines" => Some('n'),
        "full-paths" => Some('p'),
        "ignore-directory" => Some('X'),
        "ignore-all-in-file" => Some('I'),
        "dereference-links" => Some('L'),
        "limit-filesystem" => Some('x'),
        "apparent-size" => Some('s'),
        "reverse" => Some('r'),
        "no-colors" => Some('c'),
        "force-colors" => Some('C'),
        "no-percent-bars" => Some('b'),
        "bars-on-right" => Some('B'),
        "min-size" => Some('z'),
        "screen-reader" => Some('R'),
        "filecount" => Some('f'),
        "ignore-hidden" => Some('i'),
        "invert-filter" => Some('v'),
        "filter" => Some('e'),
        "file-types" => Some('t'),
        "terminal-width" => Some('w'),
        "no-progress" => Some('P'),
        "only-dir" => Some('D'),
        "only-file" => Some('F'),
        "output-format" => Some('o'),
        "stack-size" => Some('S'),
        "output-json" => Some('j'),
        "mtime" => Some('M'),
        "atime" => Some('A'),
        "ctime" => Some('y'),
        "filetime" => Some('m'),
        _ => None,
    }
}

fn no_value_allowed(value_part: Option<String>, name: &str) {
    if let Some(v) = value_part {
        die_arg(format!(
            "unexpected value '{}' for '--{}'",
            v, name
        ));
    }
}

fn get_value_from(
    _current: &str,
    value_part: Option<String>,
    raw: &[String],
    i: &mut usize,
    name: &str,
    short: Option<char>,
    kind: &str,
) -> String {
    if let Some(v) = value_part {
        return v;
    }
    *i += 1;
    if *i >= raw.len() {
        needs_value(name, short, kind)
    }
    raw[*i].clone()
}
