    exit(2);
}

fn needs_value(name: &str, short: Option<char>, kind: &str) -> ! {
    let n = match short {
        Some(c) => format!("-{}, --{} <{}>", c, name.replace('_', "-"), kind),
        None => format!("--{} <{}>", name.replace('_', "-"), kind),
    };
    let _ = n;
    let formatted = format_arg_display(name, short, kind);
    die_arg(format!(
        "a value is required for '{}' but none was supplied",
        formatted
    ))
}

fn format_arg_display(name: &str, short: Option<char>, kind: &str) -> String {
    match short {
        Some(c) => format!("-{}, --{} <{}>", c, name, kind),
        None => format!("--{} <{}>", name, kind),
    }
}

fn parse_uint(s: &str, name: &str, short: Option<char>, kind: &str) -> u64 {
    match s.parse::<u64>() {
        Ok(v) => v,
        Err(e) => {
            let display = format_arg_display(name, short, kind);
            die_arg(format!("invalid value '{}' for '{}': {}", s, display, e))
        }
    }
}

