                        args.stack_size = Some(parse_uint(&v, "stack-size", Some('S'), "STACK_SIZE"));
                        break;
                    }
                    'j' => { args.output_json = true; k += 1; }
                    'M' => {
                        let v = get_arg_val(&rest, raw, &mut i, "mtime", 'M', "MTIME");
                        args.mtime = Some(v);
                        break;
                    }
                    'A' => {
                        let v = get_arg_val(&rest, raw, &mut i, "atime", 'A', "ATIME");
                        args.atime = Some(v);
                        break;
                    }
                    'y' => {
                        let v = get_arg_val(&rest, raw, &mut i, "ctime", 'y', "CTIME");
                        args.ctime = Some(v);
                        break;
                    }
                    'm' => {
                        let v = get_arg_val(&rest, raw, &mut i, "filetime", 'm', "FILETIME");
                        if !valid_filetime(&v) {
                            die_arg(format!(
                                "invalid value '{}' for '-m, --filetime <FILETIME>'\n  [possible values: a, c, m]",
