#[derive(Clone, Copy, Debug, PartialEq)]
pub enum OutputFormat {
    Default,      // binary prefix with K, M, G, T (no unit suffix past the 1 letter)
    Si,           // SI prefix 1000-based
    Bytes,        // raw bytes
    Unit(char),   // k/m/g/t binary  
    UnitDec(char),// kb/mb/gb/tb decimal
}

impl OutputFormat {
    pub fn from_str(s: Option<&str>) -> OutputFormat {
        match s {
            None => OutputFormat::Default,
            Some("si") => OutputFormat::Si,
            Some("b") => OutputFormat::Bytes,
            Some("k") => OutputFormat::Unit('k'),
            Some("m") => OutputFormat::Unit('m'),
            Some("g") => OutputFormat::Unit('g'),
            Some("t") => OutputFormat::Unit('t'),
            Some("kb") => OutputFormat::UnitDec('k'),
            Some("mb") => OutputFormat::UnitDec('m'),
            Some("gb") => OutputFormat::UnitDec('g'),
            Some("tb") => OutputFormat::UnitDec('t'),
            _ => OutputFormat::Default,
        }
    }
}

// Format bytes in default human-readable form: e.g., 0B, 100K, 8.0K, 4.0K, 1.2M, 1.3G, 1.2T
pub fn format_size(bytes: u64, fmt: OutputFormat) -> String {
    match fmt {
        OutputFormat::Default => format_human(bytes, 1024, false),
        OutputFormat::Si => format_human(bytes, 1000, false),
        OutputFormat::Bytes => format!("{}B", bytes),
        OutputFormat::Unit(u) => format_fixed_unit(bytes, u, 1024, "iB"),
        OutputFormat::UnitDec(u) => format_fixed_unit(bytes, u, 1000, "B"),
    }
}

fn format_human(bytes: u64, base: u64, _si: bool) -> String {
    // Units for dust: B, K, M, G, T (single-letter even for SI, sometimes)
    // Actually observed: 0B, 4.0K, 100K, 1.2M, etc.
    // For si=1000, labels are the same single letters (K/M/G/T) in dust.
    let units = ["B", "K", "M", "G", "T", "P", "E"];
    let b = bytes as f64;
    let mut size = b;
    let mut idx = 0;
    let bf = base as f64;
    while size >= bf && idx < units.len() - 1 {
        size /= bf;
        idx += 1;
    }
    if idx == 0 {
        // bytes: "0B", "123B"
        return format!("{}{}", bytes, units[idx]);
    }
    // Choose display: if size < 10, show 1 decimal; else show rounded integer
    if size < 9.95 {
        format!("{:.1}{}", size, units[idx])
    } else {
        // e.g. "100K", "999K"
        format!("{:.0}{}", size, units[idx])
    }
}

fn format_fixed_unit(bytes: u64, unit: char, base: u64, suffix: &str) -> String {
    let divisor: u64 = match unit {
        'k' => base,
        'm' => base * base,
        'g' => base * base * base,
        't' => base * base * base * base,
        _ => 1,
    };
    let v = bytes as f64 / divisor as f64;
    let unit_str = match unit {
        'k' => format!("K{}", suffix),
        'm' => format!("M{}", suffix),
        'g' => format!("G{}", suffix),
        't' => format!("T{}", suffix),
        _ => suffix.to_string(),
    };
    if v < 9.95 && v > 0.0 {
        format!("{:.1}{}", v, unit_str)
    } else {
        format!("{:.0}{}", v, unit_str)
    }
}

// Parse min-size values like "10M", "1G", "500K"
pub fn parse_size_str(s: &str) -> Option<u64> {
    let t = s.trim();
    if t.is_empty() { return None; }
    let bytes = t.as_bytes();
    let mut end = 0;
    while end < bytes.len() && (bytes[end].is_ascii_digit() || bytes[end] == b'.') {
        end += 1;
    }
    let (num_str, unit_str) = (&t[..end], t[end..].trim());
    let num: f64 = num_str.parse().ok()?;
    let u = unit_str.to_lowercase();
    let mult: u64 = match u.as_str() {
        "" | "b" => 1,
        "k" | "kb" | "kib" => 1024,
        "m" | "mb" | "mib" => 1024 * 1024,
        "g" | "gb" | "gib" => 1024u64.pow(3),
        "t" | "tb" | "tib" => 1024u64.pow(4),
        _ => return None,
    };
    Some((num * mult as f64) as u64)
}
