    pub filecount: bool,
    pub min_size: Option<u64>,
    pub only_dir: bool,
    pub only_file: bool,
    pub full_paths: bool,
    pub max_depth: Option<u64>,
    pub collapse: Vec<String>,
}

impl WalkOptions {
