        fs::metadata(path)
    } else {
        fs::symlink_metadata(path)
    };
    let name = path.file_name().map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| display_path.to_string());
    match meta {
        Ok(m) => {
            // Check same filesystem
            if opts.limit_filesystem {
                if let Some(rd) = root_dev {
                    if m.dev() != rd {
                        return Node { name, full_path: display_path.to_string(), size: 0, is_dir: false, children: vec![], errored: false };
                    }
                }
            }
            let is_dir = if opts.dereference_links { m.is_dir() } else {
