    pub full_path: String,   // display path (may be relative or absolute)
    pub size: u64,
    pub is_dir: bool,
    pub children: Vec<Node>,
    pub errored: bool,
}

pub struct WalkOptions {
    pub apparent_size: bool,
    pub dereference_links: bool,
    pub limit_filesystem: bool,
    pub ignore_hidden: bool,
    pub ignore_dirs: Vec<String>,
    pub filter: Vec<String>,
    pub invert_filter: Vec<String>,
    pub filecount: bool,
    pub min_size: Option<u64>,
    pub only_dir: bool,
    pub only_file: bool,
    pub full_paths: bool,
    pub max_depth: Option<u64>,
    pub collapse: Vec<String>,
}

impl WalkOptions {
    pub fn should_ignore_name(&self, name: &str) -> bool {
        if self.ignore_hidden && name.starts_with('.') && name != "." && name != ".." {
            return true;
        }
        for d in &self.ignore_dirs {
            if name == d { return true; }
            let p = Path::new(d);
            if let Some(f) = p.file_name() {
                if f.to_string_lossy() == name { return true; }
            }
        }
        false
    }
    pub fn is_collapsed(&self, name: &str) -> bool {
        self.collapse.iter().any(|c| c == name)
    }
}

fn matches_any(path: &str, pats: &[String]) -> bool {
    // Poor-man regex: we implement a small subset.
    for p in pats {
        if crate::rx::simple_regex_search(p, path) { return true; }
    }
    false
}

pub fn walk_path(path: &Path, opts: &WalkOptions, root_dev: Option<u64>, depth: u64, display_path: &str) -> Node {
    let meta = if opts.dereference_links {
        fs::metadata(path)
    } else {
        fs::symlink_metadata(path)
    };
    let name = path.file_name().map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| display_path.to_string());
    match meta {
        Ok(m) => {
            // Check same filesystem
            if opts.limit_filesystem {
                if let Some(rd) = root_dev {
                    if m.dev() != rd {
                        return Node { name, full_path: display_path.to_string(), size: 0, is_dir: false, children: vec![], errored: false };
                    }
                }
            }
            let is_dir = if opts.dereference_links { m.is_dir() } else {
                m.file_type().is_dir() && !m.file_type().is_symlink()
            };
            let is_symlink = m.file_type().is_symlink();
            if is_dir && (opts.max_depth.map(|d| depth < d).unwrap_or(true)) && !opts.is_collapsed(&name) {
                let mut children = Vec::new();
                let mut size_bytes: u64 = 0;
                let mut filec: u64 = 0;
                let self_size = if opts.apparent_size { m.len() } else { m.blocks() * 512 };
                size_bytes += self_size;
                match fs::read_dir(path) {
                    Ok(rd) => {
                        for entry in rd.flatten() {
                            let entry_path = entry.path();
                            let child_name = entry.file_name().to_string_lossy().to_string();
                            if opts.should_ignore_name(&child_name) { continue; }
                            let child_display = if opts.full_paths {
                                entry_path.to_string_lossy().to_string()
                            } else {
                                format!("{}/{}", display_path.trim_end_matches('/'), child_name)
                            };
                            let ch = walk_path(&entry_path, opts, root_dev, depth + 1, &child_display);
                            size_bytes += ch.size;
                            filec += count_files(&ch);
