// Supports: literal characters, '.', '\.', '\w', '\d', '\s', '*', '+', '?', '^', '$'
// Character classes are NOT supported.

#[derive(Debug, Clone)]
enum Token {
    Lit(char),
    Any,             // .
    Anchor(bool),    // true=start(^), false=end($)
    Star(Box<Token>),
    Plus(Box<Token>),
    Opt(Box<Token>),
    Class(Vec<char>, bool), // class chars, negated
    Seq(Vec<Token>),
    Alt(Vec<Vec<Token>>),
}

fn parse_re(s: &str) -> Vec<Token> {
    let mut chars = s.chars().peekable();
    let mut tokens = Vec::new();
    while let Some(&c) = chars.peek() {
        chars.next();
        let tok = match c {
            '^' => Token::Anchor(true),
            '$' => Token::Anchor(false),
            '.' => Token::Any,
            '\\' => {
                if let Some(&nc) = chars.peek() {
                    chars.next();
                    match nc {
                        'd' => Token::Class(('0'..='9').collect(), false),
                        'w' => {
                            let mut v: Vec<char> = ('a'..='z').collect();
                            v.extend('A'..='Z');
                            v.extend('0'..='9');
                            v.push('_');
                            Token::Class(v, false)
                        }
                        's' => Token::Class(vec![' ', '\t', '\n', '\r'], false),
                        _ => Token::Lit(nc),
                    }
                } else {
                    Token::Lit('\\')
                }
            }
            '[' => {
                let mut negated = false;
                if let Some(&'^') = chars.peek() { negated = true; chars.next(); }
                let mut v = Vec::new();
                while let Some(&cc) = chars.peek() {
                    chars.next();
                    if cc == ']' { break; }
                    if cc == '\\' {
                        if let Some(&nc) = chars.peek() { chars.next(); v.push(nc); }
                    } else if let Some(&'-') = chars.peek() {
                        chars.next();
                        if let Some(&end) = chars.peek() {
                            if end != ']' {
                                chars.next();
                                for ch in (cc as u32)..=(end as u32) {
                                    if let Some(c) = char::from_u32(ch) { v.push(c); }
                                }
                                continue;
                            }
                        }
                        v.push(cc);
                        v.push('-');
                    } else {
                        v.push(cc);
                    }
                }
                Token::Class(v, negated)
            }
            '*' | '+' | '?' => {
                // apply to last token
                if let Some(last) = tokens.pop() {
                    let b = Box::new(last);
                    match c {
                        '*' => Token::Star(b),
                        '+' => Token::Plus(b),
                        '?' => Token::Opt(b),
                        _ => unreachable!(),
                    }
                } else {
                    Token::Lit(c)
                }
            }
            '(' => {
                let mut depth = 1;
                let mut inner = String::new();
                while let Some(&cc) = chars.peek() {
                    chars.next();
                    if cc == '\\' {
                        if let Some(&nc) = chars.peek() { chars.next(); inner.push('\\'); inner.push(nc); continue; }
                        inner.push('\\');
                        continue;
                    }
                    if cc == '(' { depth += 1; }
                    if cc == ')' { depth -= 1; if depth == 0 { break; } }
                    inner.push(cc);
                }
                // Handle alternation
                let alts: Vec<&str> = inner.split('|').collect();
                if alts.len() == 1 {
                    Token::Seq(parse_re(&inner))
                } else {
                    let alt_tokens: Vec<Vec<Token>> = alts.iter().map(|a| parse_re(a)).collect();
                    Token::Alt(alt_tokens)
                }
            }
            '|' => {
                // top-level alternation: collect what we have, then parse rest
                let rest: String = chars.collect();
                let left = std::mem::take(&mut tokens);
                let right = parse_re(&rest);
                tokens.push(Token::Alt(vec![left, right]));
                return tokens;
            }
            _ => Token::Lit(c),
        };
        tokens.push(tok);
    }
    tokens
}

fn match_tokens(toks: &[Token], s: &[char], pos: usize) -> Option<usize> {
    if toks.is_empty() { return Some(pos); }
    let (t, rest) = (&toks[0], &toks[1..]);
    match t {
        Token::Anchor(start) => {
            if *start {
                if pos == 0 { match_tokens(rest, s, pos) } else { None }
            } else {
                if pos == s.len() { match_tokens(rest, s, pos) } else { None }
            }
        }
        Token::Lit(c) => {
            if pos < s.len() && s[pos] == *c { match_tokens(rest, s, pos + 1) } else { None }
        }
        Token::Any => {
            if pos < s.len() && s[pos] != '\n' { match_tokens(rest, s, pos + 1) } else { None }
        }
        Token::Class(v, neg) => {
            if pos < s.len() {
                let inside = v.contains(&s[pos]);
                if inside ^ *neg { match_tokens(rest, s, pos + 1) } else { None }
            } else { None }
        }
        Token::Seq(ts) => {
            // Match inner sequence first, then rest
            if let Some(new_pos) = match_tokens(ts, s, pos) {
                match_tokens(rest, s, new_pos)
            } else { None }
        }
        Token::Alt(alts) => {
            for a in alts {
                if let Some(new_pos) = match_tokens(a, s, pos) {
                    if let Some(r) = match_tokens(rest, s, new_pos) { return Some(r); }
                }
            }
            None
        }
        Token::Star(inner) => {
            // Greedy
            let mut positions = vec![pos];
            let mut p = pos;
            loop {
                let one = [*(inner.clone())];
                match match_tokens(&one, s, p) {
                    Some(np) if np > p => { positions.push(np); p = np; }
                    _ => break,
                }
            }
            for &p in positions.iter().rev() {
                if let Some(r) = match_tokens(rest, s, p) { return Some(r); }
            }
            None
        }
        Token::Plus(inner) => {
            let one = [*(inner.clone())];
            let np = match_tokens(&one, s, pos)?;
            // Then zero or more
            let mut positions = vec![np];
            let mut p = np;
            loop {
                match match_tokens(&one, s, p) {
                    Some(nn) if nn > p => { positions.push(nn); p = nn; }
                    _ => break,
                }
            }
            for &p in positions.iter().rev() {
                if let Some(r) = match_tokens(rest, s, p) { return Some(r); }
            }
            None
        }
        Token::Opt(inner) => {
            let one = [*(inner.clone())];
            if let Some(np) = match_tokens(&one, s, pos) {
                if let Some(r) = match_tokens(rest, s, np) { return Some(r); }
            }
            match_tokens(rest, s, pos)
        }
    }
}

pub fn simple_regex_search(pat: &str, text: &str) -> bool {
    let toks = parse_re(pat);
    let s: Vec<char> = text.chars().collect();
    // Check anchored: if starts with ^
    let anchored_start = toks.first().map(|t| matches!(t, Token::Anchor(true))).unwrap_or(false);
    let start_range: Vec<usize> = if anchored_start { vec![0] } else { (0..=s.len()).collect() };
    for start in start_range {
        if match_tokens(&toks, &s, start).is_some() { return true; }
    }
    false
}
