// Very limited TOML subset parser for dust config.
// Supports: simple top-level `key = value` lines with booleans, integers, strings, arrays.

use std::fs;
use std::path::PathBuf;

use crate::args::Args;

pub fn load_default_config(args: &mut Args) {
    // Optionally specified config file
    if let Some(cf) = args.config.clone() {
        let _ = load_file(&cf, args);
        return;
    }
    // Default: ~/.config/dust/config.toml or ~/.dust.toml
    if let Some(home) = std::env::var_os("HOME") {
        let home = PathBuf::from(home);
        let p1 = home.join(".config/dust/config.toml");
        if p1.exists() {
            let _ = load_file(p1.to_str().unwrap_or(""), args);
            return;
        }
        let p2 = home.join(".dust.toml");
        if p2.exists() {
            let _ = load_file(p2.to_str().unwrap_or(""), args);
        }
    }
}

fn load_file(path: &str, args: &mut Args) -> Result<(), std::io::Error> {
    let content = fs::read_to_string(path)?;
    for raw_line in content.lines() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') { continue; }
        let eq = match line.find('=') { Some(i) => i, None => continue };
        let key = line[..eq].trim();
        let val = line[eq + 1..].trim();
        // Strip comments at end
        let val = strip_trailing_comment(val).trim();
        apply_kv(key, val, args);
    }
    Ok(())
}

fn strip_trailing_comment(s: &str) -> &str {
    // Find # not within quotes
    let mut in_str = false;
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'"' { in_str = !in_str; }
        if !in_str && b == b'#' { return &s[..i]; }
        i += 1;
    }
    s
}

fn parse_str(s: &str) -> Option<String> {
    let t = s.trim();
    if t.starts_with('"') && t.ends_with('"') && t.len() >= 2 {
        return Some(t[1..t.len()-1].to_string());
    }
    None
}

fn parse_bool(s: &str) -> Option<bool> {
    match s.trim() {
        "true" => Some(true),
        "false" => Some(false),
        _ => None,
    }
}

fn parse_u64(s: &str) -> Option<u64> {
    s.trim().parse().ok()
}

fn parse_array(s: &str) -> Option<Vec<String>> {
    let t = s.trim();
    if !(t.starts_with('[') && t.ends_with(']')) { return None; }
    let inner = &t[1..t.len()-1];
    let mut result = Vec::new();
    for part in inner.split(',') {
        let p = part.trim();
        if p.is_empty() { continue; }
        if let Some(v) = parse_str(p) { result.push(v); } else { result.push(p.to_string()); }
    }
    Some(result)
}

fn apply_kv(key: &str, val: &str, args: &mut Args) {
    match key {
        "depth" => { if let Some(v) = parse_u64(val) { if args.depth.is_none() { args.depth = Some(v); } } }
        "threads" => { if let Some(v) = parse_u64(val) { if args.threads.is_none() { args.threads = Some(v); } } }
        "number-of-lines" => { if let Some(v) = parse_u64(val) { if args.number_of_lines.is_none() { args.number_of_lines = Some(v); } } }
        "display-full-paths" | "full-paths" => { if let Some(v) = parse_bool(val) { if v { args.full_paths = true; } } }
        "ignore-directory" => { if let Some(v) = parse_array(val) { args.ignore_dirs.extend(v); } else if let Some(v) = parse_str(val) { args.ignore_dirs.push(v); } }
        "ignore-all-in-file" => { if let Some(v) = parse_str(val) { if args.ignore_all_in_file.is_none() { args.ignore_all_in_file = Some(v); } } }
        "dereference-links" => { if let Some(v) = parse_bool(val) { if v { args.dereference_links = true; } } }
        "limit-filesystem" => { if let Some(v) = parse_bool(val) { if v { args.limit_filesystem = true; } } }
        "display-apparent-size" | "apparent-size" => { if let Some(v) = parse_bool(val) { if v { args.apparent_size = true; } } }
        "reverse" => { if let Some(v) = parse_bool(val) { if v { args.reverse = true; } } }
        "no-colors" => { if let Some(v) = parse_bool(val) { if v { args.no_colors = true; } } }
        "force-colors" => { if let Some(v) = parse_bool(val) { if v { args.force_colors = true; } } }
        "no-percent-bars" | "no-bars" => { if let Some(v) = parse_bool(val) { if v { args.no_percent_bars = true; } } }
        "bars-on-right" => { if let Some(v) = parse_bool(val) { if v { args.bars_on_right = true; } } }
        "min-size" => { if let Some(v) = parse_str(val) { if args.min_size.is_none() { args.min_size = Some(v); } } }
        "screen-reader" => { if let Some(v) = parse_bool(val) { if v { args.screen_reader = true; } } }
        "skip-total" => { if let Some(v) = parse_bool(val) { if v { args.skip_total = true; } } }
        "filecount" => { if let Some(v) = parse_bool(val) { if v { args.filecount = true; } } }
        "ignore-hidden" => { if let Some(v) = parse_bool(val) { if v { args.ignore_hidden = true; } } }
        "invert-filter" => { if let Some(v) = parse_array(val) { args.invert_filter.extend(v); } else if let Some(v) = parse_str(val) { args.invert_filter.push(v); } }
        "filter" => { if let Some(v) = parse_array(val) { args.filter.extend(v); } else if let Some(v) = parse_str(val) { args.filter.push(v); } }
        "file-types" => { if let Some(v) = parse_bool(val) { if v { args.file_types = true; } } }
        "terminal-width" => { if let Some(v) = parse_u64(val) { if args.terminal_width.is_none() { args.terminal_width = Some(v); } } }
        "no-progress" => { if let Some(v) = parse_bool(val) { if v { args.no_progress = true; } } }
        "print-errors" => { if let Some(v) = parse_bool(val) { if v { args.print_errors = true; } } }
        "only-dir" => { if let Some(v) = parse_bool(val) { if v { args.only_dir = true; } } }
        "only-file" => { if let Some(v) = parse_bool(val) { if v { args.only_file = true; } } }
        "output-format" => { if let Some(v) = parse_str(val) { if args.output_format.is_none() { args.output_format = Some(v); } } }
        "stack-size" => { if let Some(v) = parse_u64(val) { if args.stack_size.is_none() { args.stack_size = Some(v); } } }
        "output-json" => { if let Some(v) = parse_bool(val) { if v { args.output_json = true; } } }
        "mtime" => { if let Some(v) = parse_str(val) { if args.mtime.is_none() { args.mtime = Some(v); } } }
        "atime" => { if let Some(v) = parse_str(val) { if args.atime.is_none() { args.atime = Some(v); } } }
        "ctime" => { if let Some(v) = parse_str(val) { if args.ctime.is_none() { args.ctime = Some(v); } } }
        "collapse" => { if let Some(v) = parse_array(val) { args.collapse.extend(v); } else if let Some(v) = parse_str(val) { args.collapse.push(v); } }
        "filetime" => { if let Some(v) = parse_str(val) { if args.filetime.is_none() { args.filetime = Some(v); } } }
        _ => {}
    }
}
