}

pub fn detect_terminal_width() -> usize {
    if let Some(w) = env_parse("COLUMNS") { return w; }
    if let Some((w, _)) = tty_size() { return w; }
    80
}

pub fn detect_terminal_height() -> usize {
    if let Some(h) = env_parse("LINES") { return h; }
    if let Some((_, h)) = tty_size() { return h; }
    24
}

fn env_parse(name: &str) -> Option<usize> {
    std::env::var(name).ok().and_then(|s| s.parse().ok())
}

fn tty_size() -> Option<(usize, usize)> {
    use std::os::unix::io::AsRawFd;
    #[repr(C)]
    struct Winsize { ws_row: u16, ws_col: u16, _x: u16, _y: u16 }
    extern "C" { fn ioctl(fd: i32, req: u64, ...) -> i32; }
    let fd = std::io::stdout().as_raw_fd();
    let mut ws = Winsize { ws_row: 0, ws_col: 0, _x: 0, _y: 0 };
    // TIOCGWINSZ = 0x5413 on linux
    let r = unsafe { ioctl(fd, 0x5413, &mut ws) };
    if r == 0 && ws.ws_col > 0 { Some((ws.ws_col as usize, ws.ws_row as usize)) } else { None }
}

// Aggregate all nodes into a single virtual root. Adds "(total)" label when multiple paths.
pub fn to_display_tree(nodes: Vec<Node>, screen_reader: bool) -> Node {
    let _ = screen_reader;
    if nodes.len() == 1 {
        return nodes.into_iter().next().unwrap();
    }
    // Multiple root paths => wrap in synthetic "(total)" root
    let total: u64 = nodes.iter().map(|n| n.size).sum();
    Node {
        name: "(total)".to_string(),
        full_path: "(total)".to_string(),
        size: total,
        is_dir: true,
        children: nodes,
        errored: false,
    }
}

// DFS and emit lines in post-order (children first ascending, then parent)
// Each entry has the visual depth and whether it's first/middle/last of its siblings AT print time.
// In default mode, for siblings sorted ascending, the "last" to be printed is actually the parent (merger) 
// which has a `┌─┴` on first use or `├─┴` on later use.
// In reverse mode, we sort descending and reverse order.

pub struct Row {
    pub size: u64,
    pub name: String,
    pub display_name: String,
    pub depth: usize,
    pub tree_chars: String, // e.g. "┌──", "├──", "┌─┴", "├─┴"
    pub indent: usize, // number of leading spaces before tree_chars
    pub is_dir_merger: bool,
    pub full_path: String,
}

pub fn flatten_tree(root: &Node, opts: &DisplayOpts, max_rows: usize) -> Vec<Row> {
    // 1) First, limit by picking top-N biggest over the tree (excluding root if total displayed).
    // dust's actual algorithm prunes nodes such that only top-N by size (kind of) are shown.
    // We'll do: show the root, plus pick top (max_rows - 1) by size.
    let mut rows: Vec<Row> = Vec::new();
    let kept = select_top_n(root, max_rows, opts);
    walk_and_emit(root, 0, &kept, opts, true, &mut rows);
    // Compute tree_chars for each row based on their depth and sibling position.
    assign_tree_chars(&mut rows, opts);
    rows
}

// Select which nodes to show based on size
fn select_top_n(root: &Node, max_rows: usize, opts: &DisplayOpts) -> std::collections::HashSet<*const Node> {
    use std::collections::{BinaryHeap, HashSet};
    // Simple approach: BFS by size, always include root, then biggest descendants.
    let mut kept: HashSet<*const Node> = HashSet::new();
    kept.insert(root as *const Node);
    let skip_total_adjusted = if opts.skip_total { max_rows } else { max_rows.saturating_sub(1) } + 1;
    let limit = max_rows;
    // Collect all descendants (not root) with pointer and depth
    let mut all: Vec<(u64, *const Node, *const Node)> = Vec::new(); // (size, ptr, parent_ptr)
    collect_all(root, root, &mut all);
    // Sort by size descending
    all.sort_by(|a, b| b.0.cmp(&a.0));
    // We need to include nodes such that for any included node, its parent must be in the kept set.
    // Pass: add biggest, ensuring parent is kept.
    for (_, n, _) in &all {
        if kept.len() >= limit { break; }
        // Add if parent is in kept, otherwise skip
        // Find ancestry chain from root
        let node_ref = unsafe { &**n };
        let ancestors = find_ancestors(root, node_ref);
        let mut all_kept = true;
        for a in &ancestors {
            if !kept.contains(&(*a as *const Node)) { all_kept = false; break; }
        }
        if all_kept { kept.insert(*n); }
    }
    // If we still have capacity, expand to include more by fitting parent-first constraints
    let _ = skip_total_adjusted;
    kept
}

fn find_ancestors<'a>(root: &'a Node, target: &Node) -> Vec<&'a Node> {
    let mut stack: Vec<&'a Node> = Vec::new();
    fn inner<'a>(cur: &'a Node, target: *const Node, stack: &mut Vec<&'a Node>) -> bool {
        stack.push(cur);
        if (cur as *const Node) == target {
            // remove self
            stack.pop();
            return true;
        }
        for c in &cur.children {
            if inner(c, target, stack) { return true; }
        }
        stack.pop();
        false
    }
    inner(root, target as *const Node, &mut stack);
    stack
}

fn collect_all<'a>(root: &'a Node, cur: &'a Node, out: &mut Vec<(u64, *const Node, *const Node)>) {
    for c in &cur.children {
        out.push((c.size, c as *const Node, cur as *const Node));
        collect_all(root, c, out);
    }
}

fn walk_and_emit(
    node: &Node,
    depth: usize,
    kept: &std::collections::HashSet<*const Node>,
    opts: &DisplayOpts,
    is_root: bool,
    out: &mut Vec<Row>,
) {
    // Sort children: ascending for default, descending for reverse
    let mut kept_children: Vec<&Node> = node.children.iter()
        .filter(|c| kept.contains(&(*c as *const Node)))
        .collect();
    if opts.reverse {
        kept_children.sort_by(|a, b| b.size.cmp(&a.size).then_with(|| a.name.cmp(&b.name)));
    } else {
        kept_children.sort_by(|a, b| a.size.cmp(&b.size).then_with(|| a.name.cmp(&b.name)));
    }
    let has_children = !kept_children.is_empty();
    // Skip total?
    let emit_self = !(is_root && opts.skip_total && !node.children.is_empty() && !is_single_file(node));
    // For reverse mode: parent first, then children
    if opts.reverse && emit_self {
        out.push(Row {
            size: node.size,
            name: node.name.clone(),
            display_name: display_name_for(node, opts, depth),
            depth,
            tree_chars: String::new(),
            indent: depth * 2,
            is_dir_merger: has_children,
            full_path: node.full_path.clone(),
        });
    }
    for c in &kept_children {
        walk_and_emit(c, depth + 1, kept, opts, false, out);
    }
    if !opts.reverse && emit_self {
        out.push(Row {
            size: node.size,
            name: node.name.clone(),
            display_name: display_name_for(node, opts, depth),
            depth,
            tree_chars: String::new(),
            indent: depth * 2,
            is_dir_merger: has_children,
            full_path: node.full_path.clone(),
        });
    }
}

fn is_single_file(n: &Node) -> bool { !n.is_dir && n.children.is_empty() }

fn display_name_for(n: &Node, opts: &DisplayOpts, depth: usize) -> String {
    if opts.full_paths {
        n.full_path.clone()
    } else {
        // For root level (depth==0), show the path as provided.
        if depth == 0 {
            n.full_path.clone()
        } else {
            n.name.clone()
        }
    }
}

// Assign tree_chars per row.
// For each "column" (depth), find all rows that use it, and label the first/middle/last occurrences.
// Each row uses its own column; merger rows also "use" child_col (via `┴` or `┬`).
fn assign_tree_chars(rows: &mut Vec<Row>, opts: &DisplayOpts) {
    use std::collections::BTreeMap;
    let mut col_rows: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
    // For each row, add its own col
    for (i, r) in rows.iter().enumerate() {
        col_rows.entry(r.depth).or_default().push(i);
    }
    // Decide tree chars
    // For each row, find whether it's first/middle/last at its column.
    for (i, r) in rows.iter_mut().enumerate() {
        let col = r.depth;
        let list = col_rows.get(&col).unwrap();
        let pos = list.iter().position(|&x| x == i).unwrap();
        let is_first = pos == 0;
        let is_last_at_col = pos == list.len() - 1;
        // In default mode: the "last use" of a column is the parent merger's `┴`.
        // So a leaf's tree char is `┌──` if first, else `├──` (even if last).
        // In reverse mode: `└──` if last; else `├──`; parent merger starts with `┬` at top.
        let chars = if opts.reverse {
            if r.is_dir_merger {
                if is_first { "└─┬".to_string() } else { "├─┬".to_string() }
            } else {
                if is_last_at_col { "└──".to_string() } else { "├──".to_string() }
            }
        } else {
            if r.is_dir_merger {
                if is_first { "┌─┴".to_string() } else { "├─┴".to_string() }
            } else {
                if is_first { "┌──".to_string() } else { "├──".to_string() }
            }
        };
        r.tree_chars = chars;
    }
}

pub fn compute_tree_and_name_col_width(rows: &[Row], opts: &DisplayOpts) -> (usize, Vec<String>, Vec<String>) {
    // For each row compute prefix (indent + tree) and body (name part).
    // Prefix width = indent + 3 (tree chars are 3 chars)
    // The alignment rule: tree chars at col (5 + 2*depth) where 5 is the root col, adjusted by size column
    // We'll render "prefix spaces + tree chars + space + name" and pad to max.
    let mut prefixes = Vec::with_capacity(rows.len());
    let mut names = Vec::with_capacity(rows.len());
    let mut max_prefix = 0;
    for r in rows {
        let indent = r.indent;
        prefixes.push((indent, r.tree_chars.clone()));
        names.push(r.display_name.clone());
        let content_len = indent + display_width(&r.tree_chars) + 1 + display_width(&r.display_name);
        if content_len > max_prefix { max_prefix = content_len; }
    }
    // Convert prefix data to strings (with vertical bars filled)
    let prefix_strs = build_prefix_strings(rows, opts);
    (max_prefix, prefix_strs, names)
}

// Build prefix strings for each row: leading spaces, `│` at ancestor cols that need extension.
fn build_prefix_strings(rows: &[Row], opts: &DisplayOpts) -> Vec<String> {
    let n = rows.len();
    // For each column, determine which rows "use" that column (draw a tree char at that col).
    // Then, a row draws `│` at col if there's a usage both before and after the current row.
    let mut col_has_usage: Vec<Vec<bool>> = vec![Vec::new(); n];
    // For each row, we compute which cols are "occupied" by a tree char
    let max_depth = rows.iter().map(|r| r.depth).max().unwrap_or(0);
    // 2D: is_tree_char_at[row][col]
    let mut occupied: Vec<Vec<bool>> = vec![vec![false; max_depth + 1]; n];
    for (i, r) in rows.iter().enumerate() {
        occupied[i][r.depth] = true;
        // merger rows also place a `┴` or `┬` at child col (r.depth + 1)
        if r.is_dir_merger && r.depth + 1 <= max_depth {
            occupied[i][r.depth + 1] = true;
        }
    }
    // For each col, find min/max occupied row index
    let mut col_range: Vec<(usize, usize, bool)> = Vec::with_capacity(max_depth + 1);
    for c in 0..=max_depth {
        let mut first = None;
        let mut last = None;
        for i in 0..n {
            if occupied[i][c] {
                if first.is_none() { first = Some(i); }
                last = Some(i);
            }
        }
        col_range.push((first.unwrap_or(0), last.unwrap_or(0), first.is_some()));
    }
    // Now build strings
    let mut out = Vec::with_capacity(n);
    for (i, r) in rows.iter().enumerate() {
        let mut s = String::new();
        // Width: indent is r.depth * 2 spaces. But we need to replace cols that need a `│` (those cols where row is between col_range's min and max exclusive, and not occupied)
        // Actually output: for c in 0..r.depth, two chars (space + char at that col)
        // Let's construct: for each col 0..=max_depth with char placement:
        // Actually the rendering format:
        //   leading content = for each depth d from 0 to r.depth:
        //     2 chars, first being a space, second being either ' ' or '│' or the tree char
        // then the tree chars of r start at position (r.depth * 2 + 1)?
        // Hmm. Let's just build column-by-column.
        //
        // Format per col: space + content char
        // For cols 0..r.depth: space + ('│' if needs extension else ' ')
        // At col r.depth: space + first char of tree_chars[0]
        // (tree_chars is 3 chars, second is `─`, third is `┴` or `─` etc)
        // Actually the tree chars span 3 columns (r.depth, r.depth+1 indirectly since ─┴).
        // Let me reconsider: a tree char like `┌─┴` starts at col r.depth occupying 3 "char" positions but we want to align so that `┌` is at col (base + 2*r.depth) and `┴` or the terminal part is at col (base + 2*r.depth + 2).
        // base = 0 from prefix start.
        // So total prefix width = 2 * r.depth + 3 + 1 (space) + name
        // Actually per our observation: each depth adds 2 spaces, then at the deepest level is 3 chars of tree.
        // Build: first r.depth pairs of (space, char), then the 3-char tree, then space + name.
        for c in 0..r.depth {
            // at this col, show `│` if (col_range[c].2 && first <= i <= last && !occupied[i][c])
            s.push(' ');
            let cr = col_range[c];
            let show_bar = cr.2 && i > cr.0 && i < cr.1 && !occupied[i][c];
            if show_bar { s.push('│'); } else { s.push(' '); }
        }
        // Then space + tree_chars (3 chars) + space + name
        s.push(' ');
        s.push_str(&r.tree_chars);
        s.push(' ');
        s.push_str(&r.display_name);
        out.push(s);
    }
    out
}

fn display_width(s: &str) -> usize {
    // Each char counts as 1 (box chars, etc.) - this is sufficient for our alignment purposes
    s.chars().count()
}

pub fn print_tree(rows: Vec<Row>, opts: &DisplayOpts) {
    if rows.is_empty() { return; }
    // Compute sizes column width
    let mut size_strs: Vec<String> = rows.iter().map(|r| format_size_for_row(r, opts)).collect();
    let size_w = size_strs.iter().map(|s| s.chars().count()).max().unwrap_or(1);
    // Right-justify sizes
    for s in size_strs.iter_mut() {
        let sw = s.chars().count();
        if sw < size_w { *s = format!("{}{}", " ".repeat(size_w - sw), s); }
    }
    let prefix_strs = build_prefix_strings(&rows, opts);
    let name_area_max = prefix_strs.iter().map(|s| s.chars().count()).max().unwrap_or(0);
    // Build full lines
    // At display_width, remaining for bar:
    // total = size_w + 1 + name_area_max + 1 + bar_w + 1 + 5
    let percent_w = 5; // "   0%" style
    if opts.screen_reader {
        // Screen reader: no bars, no fancy tree; show name, depth, size, percent
        // Format observed:
        // c       3   0B   0%
        // name (padded), depth, size (padded), percent (padded)
        let names: Vec<String> = rows.iter().map(|r| r.name.clone()).collect();
        let max_name = names.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        let max_size = size_strs.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        let total = rows.iter().find(|r| r.depth == 0).map(|r| r.size).unwrap_or(1).max(1);
        for (i, r) in rows.iter().enumerate() {
            let pct = (r.size as f64 * 100.0 / total as f64).round() as u64;
            let pct_s = format!("{}%", pct);
            let pct_padded = format!("{:>4}", pct_s);
            let name = format!("{:<width$}", r.name, width = max_name);
            let size = format!("{:>width$}", size_strs[i], width = max_size);
            println!("{} {} {} {}", name, r.depth, size, pct_padded);
        }
        return;
    }
    let fixed = size_w + 1 + name_area_max + 1 + 1 + percent_w;
    let bar_w = opts.terminal_width.saturating_sub(fixed).max(1);
    let total = rows.iter().find(|r| r.depth == 0).map(|r| r.size).unwrap_or(1).max(1);

    if opts.no_percent_bars {
        for (i, r) in rows.iter().enumerate() {
            let _ = r;
            let prefix = &prefix_strs[i];
            let padded_prefix = format!("{:<width$}", prefix, width = name_area_max);
            println!("{} {}", size_strs[i], padded_prefix.trim_end());
        }
        return;
    }

    // Determine bar widths for each node (size relative to total)
    let bar_widths: Vec<usize> = rows.iter().map(|r| {
        if r.size == 0 { 1 } else {
            let w = (r.size as f64 / total as f64 * bar_w as f64).round() as usize;
            w.max(1).min(bar_w)
        }
    }).collect();

    // Output each row
    for (i, r) in rows.iter().enumerate() {
        let prefix = &prefix_strs[i];
        let padded_prefix = pad_right(prefix, name_area_max);
        // Compute bar for this row
        let own_w = bar_widths[i];
        // Find ancestor widths (non-root) that reach beyond own_w
        // Ancestors are rows with depth < r.depth that are along the path from root to r
        // We'll approximate: find all ancestor widths by walking up using `depth` and the structure.
        let mut bar = String::new();
        // Build bar chars
        // Identify ancestors for this row: look for the tree structure. Since rows are laid out, we need ancestor row indices.
        let ancestor_indices = find_ancestor_indices(&rows, i);
        let ancestor_widths: Vec<usize> = ancestor_indices.iter()
            .map(|&ai| bar_widths[ai])
            .collect();
        // root's width equals total's bar (which is bar_w). We ignore root (depth 0).
        // Which ancestors are non-root? All except depth 0.
        let non_root_ancestors: Vec<usize> = ancestor_indices.iter().enumerate()
            .filter(|(_, &ai)| rows[ai].depth != 0)
            .map(|(_, &ai)| bar_widths[ai])
            .collect();
        let mut left_spaces = 0usize;
        let mut left_filled = own_w;
        // Bar positions from 1..=bar_w
        // Count ancestors reaching each pos
        let mut chars: Vec<char> = vec![' '; bar_w];
        for p in 0..bar_w {
            let pos = p + 1;
            if pos <= own_w {
                chars[p] = '█';
            } else {
                let mut cnt = 0usize;
                for &w in &non_root_ancestors {
                    if pos <= w { cnt += 1; }
                }
                chars[p] = if cnt >= 2 { '▒' } else if cnt == 1 { '░' } else { ' ' };
            }
        }
        let _ = left_spaces; let _ = left_filled;
        if opts.bars_on_right {
            // Reverse bar, right-align inside
            let rev: String = chars.iter().rev().collect();
            bar = rev;
        } else {
            bar = chars.iter().collect();
        }
        let pct = ((r.size as f64 / total as f64) * 100.0).round() as u64;
        let pct_s = format!("{:>3}%", pct);
        println!("{} {}│{}│ {}", size_strs[i], padded_prefix, bar, pct_s);
    }
}

fn pad_right(s: &str, width: usize) -> String {
    let cw = s.chars().count();
    if cw >= width { s.to_string() } else { format!("{}{}", s, " ".repeat(width - cw)) }
}

fn format_size_for_row(r: &Row, opts: &DisplayOpts) -> String {
    if opts.filecount {
        format!("{}", r.size)
    } else {
        format_size(r.size, opts.output_format)
    }
}

fn find_ancestor_indices(rows: &[Row], i: usize) -> Vec<usize> {
    // Find the row indices of ancestors of row i using the topological order and depth.
    // Default mode: children come before parent. Parent's depth = child's depth - 1 and it's the next row at that depth.
    // Reverse mode: parent comes before children. Then parent is the previous row at depth-1.
    let mut ancestors = Vec::new();
    let mut cur_depth = rows[i].depth;
    // We don't know the mode from rows; infer by checking whether any sibling is above or below.
    // Simpler: scan both directions. We'll use the tree structure encoded in depth.
    // Find ancestor by iterating: for each depth d = cur_depth - 1 .. 0,
    // find the nearest row with that depth that encloses row i.
    // In default mode (children first): parent is at first j > i with depth == d.
    // In reverse mode: parent is at last j < i with depth == d.
    // We'll check both directions.
    // The reasonable assumption: the path is unique; we identify ancestor via depth change.
    // For default mode: scan FORWARD, at each depth decrement, take first with depth==new_depth.
    let n = rows.len();
    // Try forward (default)
    let mut ok = true;
    let mut ancestors_fwd: Vec<usize> = Vec::new();
    let mut d = cur_depth;
    let mut j = i;
    while d > 0 {
        d -= 1;
        let mut found = None;
        for k in (j+1)..n {
            if rows[k].depth == d && rows[k].depth < rows[k - 1].depth.saturating_add(0) {
                // skip; we want the closing parent
            }
            if rows[k].depth < d { found = None; break; }
            if rows[k].depth == d { found = Some(k); break; }
        }
        if let Some(f) = found { ancestors_fwd.push(f); j = f; } else { ok = false; break; }
    }
    if ok && !ancestors_fwd.is_empty() {
        // Good, default mode
        return ancestors_fwd;
    }
    // Try backward (reverse mode)
    let mut ancestors_bwd: Vec<usize> = Vec::new();
    let mut d = cur_depth;
    let mut j = i;
    while d > 0 {
        d -= 1;
        let mut found = None;
        let mut k = j;
        while k > 0 {
            k -= 1;
            if rows[k].depth < d { break; }
            if rows[k].depth == d { found = Some(k); break; }
        }
        if let Some(f) = found { ancestors_bwd.push(f); j = f; } else { break; }
    }
    ancestors_bwd
}
