pub fn build_prefix_strings(rows: &[Row]) -> Vec<String> {
    let n = rows.len();
    let max_depth = rows.iter().map(|r| r.depth).max().unwrap_or(0);
    // occupied[i][c] = true if row i places a tree character at col c
    let mut occupied: Vec<Vec<bool>> = vec![vec![false; max_depth + 1]; n];
    for (i, r) in rows.iter().enumerate() {
        if r.depth <= max_depth { occupied[i][r.depth] = true; }
        if r.is_dir_merger && r.depth + 1 <= max_depth {
            occupied[i][r.depth + 1] = true;
        }
    }
    // For each column, find first and last occupied row indices
    let mut col_range: Vec<(usize, usize, bool)> = Vec::with_capacity(max_depth + 1);
    for c in 0..=max_depth {
        let mut first = None;
        let mut last = None;
        for i in 0..n {
            if occupied[i][c] {
                if first.is_none() { first = Some(i); }
                last = Some(i);
            }
        }
        col_range.push((first.unwrap_or(0), last.unwrap_or(0), first.is_some()));
    }

    let mut out = Vec::with_capacity(n);
    for (i, r) in rows.iter().enumerate() {
        let mut s = String::new();
        for c in 0..r.depth {
            let cr = col_range[c];
            let show_bar = cr.2 && i > cr.0 && i < cr.1 && !occupied[i][c];
            if show_bar { s.push('│'); } else { s.push(' '); }
            s.push(' ');
        }
        s.push_str(&r.tree_chars);
        s.push(' ');
        s.push_str(&r.display_name);
        out.push(s);
    }
    out
}

fn display_width(s: &str) -> usize { s.chars().count() }

pub fn print_tree(rows: Vec<Row>, opts: &DisplayOpts) {
    if rows.is_empty() { return; }
    let mut size_strs: Vec<String> = rows.iter().map(|r| format_size_for_row(r, opts)).collect();
    let size_w = size_strs.iter().map(|s| s.chars().count()).max().unwrap_or(1);
    for s in size_strs.iter_mut() {
        let sw = s.chars().count();
        if sw < size_w { *s = format!("{}{}", " ".repeat(size_w - sw), s); }
    }
    let prefix_strs = build_prefix_strings(&rows);
    let name_area_max = prefix_strs.iter().map(|s| display_width(s)).max().unwrap_or(0);

    let percent_w = 5;

    if opts.screen_reader {
        let names: Vec<String> = rows.iter().map(|r| r.name.clone()).collect();
        let max_name = names.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        let max_size = size_strs.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        let total = rows.iter().find(|r| r.depth == 0).map(|r| r.size).unwrap_or(1).max(1);
        for (i, r) in rows.iter().enumerate() {
            let pct = (r.size as f64 * 100.0 / total as f64).round() as u64;
            let pct_s = format!("{}%", pct);
            let pct_padded = format!("{:>4}", pct_s);
            let name = format!("{:<width$}", r.name, width = max_name);
            let size = format!("{:>width$}", size_strs[i], width = max_size);
            println!("{} {} {} {}", name, r.depth, size, pct_padded);
        }
        return;
    }

    if opts.no_percent_bars {
        for (i, r) in rows.iter().enumerate() {
            let _ = r;
            let prefix = &prefix_strs[i];
            println!("{} {}", size_strs[i], prefix.trim_end());
        }
        return;
    }

    let fixed = size_w + 1 + name_area_max + 1 + 1 + percent_w;
    let bar_w = opts.terminal_width.saturating_sub(fixed).max(1);
    let total = rows.iter().find(|r| r.depth == 0).map(|r| r.size).unwrap_or(1).max(1);

    // Compute bar block counts using ceil((size/total) * (bar_w - 1))
    let bar_max = (bar_w as i64 - 1).max(1) as usize;
    let bar_widths: Vec<usize> = rows.iter().map(|r| {
        let v = (r.size as f64 / total as f64 * bar_max as f64).ceil() as i64;
        v.max(1).min(bar_max as i64) as usize
    }).collect();

    // For each row, we need ancestor widths (non-root). Build ancestor chain via parent_row.
    let ancestor_widths: Vec<Vec<usize>> = rows.iter().enumerate().map(|(i, _)| {
        let mut a = Vec::new();
        let mut cur = rows[i].parent_row;
        while let Some(p) = cur {
            if rows[p].depth != 0 {
                a.push(bar_widths[p]);
            }
            cur = rows[p].parent_row;
        }
        a
    }).collect();

    for (i, r) in rows.iter().enumerate() {
        let prefix = &prefix_strs[i];
        let padded_prefix = pad_right(prefix, name_area_max);
        let own_w = bar_widths[i];
        let anc = &ancestor_widths[i];
        let mut chars: Vec<char> = vec![' '; bar_w];
        for p in 0..bar_w {
            let pos = p + 1;
            if pos <= own_w {
                chars[p] = '█';
            } else {
                let mut cnt = 0usize;
                for &w in anc { if pos <= w { cnt += 1; } }
                chars[p] = if cnt >= 2 { '▒' } else if cnt == 1 { '░' } else { ' ' };
            }
        }
        let bar: String = if opts.bars_on_right {
            chars.iter().rev().collect()
        } else {
            chars.iter().collect()
        };
        let pct = ((r.size as f64 / total as f64) * 100.0).round() as u64;
        let pct_s = format!("{:>3}%", pct);
        println!("{} {}│{}│ {}", size_strs[i], padded_prefix, bar, pct_s);
    }
}

fn pad_right(s: &str, width: usize) -> String {
    let cw = display_width(s);
    if cw >= width { s.to_string() } else { format!("{}{}", s, " ".repeat(width - cw)) }
}

fn format_size_for_row(r: &Row, opts: &DisplayOpts) -> String {
    if opts.filecount {
        format!("{}", r.size)
    } else {
        format_size(r.size, opts.output_format)
    }
}
