    if !opts.reverse && emit_self {
        let idx = out.len();
        // For children, their parent_row should point to this row
        // Fix up children's parent_row to point to this row
        // children already emitted before self; we need to find them
        // Actually, they don't have parent_row set - we'll set it here
        // We'll find immediate children by walking kept_children and looking for matching names
        // Better approach: pass parent_row down. Already done, but for default mode we don't have self_idx yet.
        out.push(Row {
            size: node.size,
            name: node.name.clone(),
            display_name: display_name_for(node, opts, depth),
            depth,
            tree_chars: String::new(),
            is_dir_merger: has_children,
            full_path: node.full_path.clone(),
            parent_row: parent_row_idx,
        });
        self_idx = Some(idx);
        // Assign parent_row to kept_children rows that are at depth+1 and are immediately before this index
        // Simplest: scan backward from idx-1, find rows at depth+1 that have parent_row == None
        // and which are "inside" this subtree (rows at depth > depth, until we hit depth <= our depth).
        if let Some(s) = self_idx {
            let mut i = s;
            while i > 0 {
                i -= 1;
                if out[i].depth <= depth { break; }
                if out[i].depth == depth + 1 && out[i].parent_row.is_none() {
                    out[i].parent_row = Some(s);
                }
            }
        }
    }
}

