pub fn flatten_tree(root: &Node, opts: &DisplayOpts, max_rows: usize) -> Vec<Row> {
    let kept = select_top_n(root, max_rows, opts);
    let mut rows: Vec<Row> = Vec::new();
    walk_and_emit(root, 0, None, &kept, opts, true, &mut rows);
    assign_tree_chars(&mut rows, opts);
    rows
}

fn select_top_n(root: &Node, max_rows: usize, opts: &DisplayOpts) -> std::collections::HashSet<*const Node> {
    use std::collections::HashSet;
    let mut kept: HashSet<*const Node> = HashSet::new();
    kept.insert(root as *const Node);
    // collect all (size, node ptr)
    let mut all: Vec<(u64, *const Node)> = Vec::new();
    collect_descendants(root, &mut all);
    all.sort_by(|a, b| b.0.cmp(&a.0));
    let limit = max_rows;
    let _ = opts;
    for (_, n) in &all {
        if kept.len() >= limit { break; }
        let node_ref = unsafe { &**n };
        let ancestors = find_ancestors(root, node_ref);
        let mut all_kept = true;
        for a in &ancestors {
            if !kept.contains(&(*a as *const Node)) { all_kept = false; break; }
        }
        if all_kept { kept.insert(*n); }
    }
    kept
}

fn find_ancestors<'a>(root: &'a Node, target: &Node) -> Vec<&'a Node> {
    let mut stack: Vec<&'a Node> = Vec::new();
    fn inner<'a>(cur: &'a Node, target: *const Node, stack: &mut Vec<&'a Node>) -> bool {
        stack.push(cur);
        if (cur as *const Node) == target {
            stack.pop();
            return true;
        }
        for c in &cur.children {
            if inner(c, target, stack) { return true; }
        }
        stack.pop();
        false
    }
    inner(root, target as *const Node, &mut stack);
    stack
}

fn collect_descendants<'a>(cur: &'a Node, out: &mut Vec<(u64, *const Node)>) {
    for c in &cur.children {
        out.push((c.size, c as *const Node));
        collect_descendants(c, out);
    }
}

fn walk_and_emit(
    node: &Node,
    depth: usize,
    parent_row_idx: Option<usize>,
    kept: &std::collections::HashSet<*const Node>,
    opts: &DisplayOpts,
    is_root: bool,
    out: &mut Vec<Row>,
) {
    let mut kept_children: Vec<&Node> = node.children.iter()
        .filter(|c| kept.contains(&(*c as *const Node)))
        .collect();
    if opts.reverse {
        kept_children.sort_by(|a, b| b.size.cmp(&a.size).then_with(|| a.name.cmp(&b.name)));
    } else {
        kept_children.sort_by(|a, b| a.size.cmp(&b.size).then_with(|| a.name.cmp(&b.name)));
    }
    let has_children = !kept_children.is_empty();
    let emit_self = !(is_root && opts.skip_total && !node.children.is_empty());

    let mut self_idx: Option<usize> = None;
    if opts.reverse && emit_self {
        let idx = out.len();
        out.push(Row {
            size: node.size,
            name: node.name.clone(),
            display_name: display_name_for(node, opts, depth),
            depth,
            tree_chars: String::new(),
            is_dir_merger: has_children,
            full_path: node.full_path.clone(),
            parent_row: parent_row_idx,
        });
        self_idx = Some(idx);
    }
    for c in kept_children.iter() {
        let pidx = if opts.reverse { self_idx } else { None };
        walk_and_emit(c, depth + 1, pidx, kept, opts, false, out);
    }
    if !opts.reverse && emit_self {
        let idx = out.len();
        // For children, their parent_row should point to this row
        // Fix up children's parent_row to point to this row
        // children already emitted before self; we need to find them
        // Actually, they don't have parent_row set - we'll set it here
        // We'll find immediate children by walking kept_children and looking for matching names
        // Better approach: pass parent_row down. Already done, but for default mode we don't have self_idx yet.
        out.push(Row {
            size: node.size,
            name: node.name.clone(),
            display_name: display_name_for(node, opts, depth),
            depth,
            tree_chars: String::new(),
            is_dir_merger: has_children,
            full_path: node.full_path.clone(),
            parent_row: parent_row_idx,
        });
        self_idx = Some(idx);
        // Assign parent_row to kept_children rows that are at depth+1 and are immediately before this index
        // Simplest: scan backward from idx-1, find rows at depth+1 that have parent_row == None
        // and which are "inside" this subtree (rows at depth > depth, until we hit depth <= our depth).
        if let Some(s) = self_idx {
            let mut i = s;
            while i > 0 {
                i -= 1;
                if out[i].depth <= depth { break; }
                if out[i].depth == depth + 1 && out[i].parent_row.is_none() {
                    out[i].parent_row = Some(s);
                }
            }
        }
    }
}

fn display_name_for(n: &Node, opts: &DisplayOpts, depth: usize) -> String {
    if opts.full_paths {
        n.full_path.clone()
    } else if depth == 0 {
        n.full_path.clone()
    } else {
        n.name.clone()
    }
}

fn assign_tree_chars(rows: &mut Vec<Row>, opts: &DisplayOpts) {
    // For each parent, find its children in print order.
    // First printed child -> `┌──` (default) or `└──` (reverse)
    // Other children -> `├──`
    // Directory mergers: `┌─┴`/`├─┴` (default), `└─┬`/`├─┬` (reverse)
    let n = rows.len();
    let mut first_seen_for_parent: std::collections::HashMap<Option<usize>, bool> = std::collections::HashMap::new();
    // In default mode, iterate 0..n (first sibling = first printed, which is first encounter of that parent)
    // In reverse mode, children are printed AFTER parent, so also iterate 0..n but the parent comes first.
    // Reverse mode: last printed child (bottom) should be `└`. Other children `├`.
    // With reverse: parents print before children. So first child encountered is actually the topmost child in display.
    // Hmm actually let me think. In reverse mode, we print parent first then children (biggest to smallest).
    // For reverse tree chars: the TOPMOST of siblings is the first encountered (parent-before-children means biggest child is first).
    // The BOTTOMMOST (last encountered) child uses `└`.
    // Middle siblings use `├`.
    // Directory mergers: first encountered at a given parent's subtree is `└─┬`? Actually in reverse, parent comes before any child.
    // Hmm. From sample, reverse mode:
    // 108K └─┬ .
    // 100K   ├─┬ d
    // 100K   │ └── big.bin
    // 8.0K   └─┬ a
    // ...
    //   0B       └── c
    //
    // So `.` is `└─┬` (first printing at its col, which is the TOP when reversed).
    // `d` is `├─┬`. big.bin is `└──` (only child of d, also the last at its col section).
    // `a` is `└─┬` (a is AFTER d's subtree, and a is the last child of .).
    // 
    // Looking: `.` has children [d, a]. In reverse, bigger first, so d then a. So d printed BEFORE a.
    // d=`├─┬` (not first of .'s children? but printed first?).
    // a=`└─┬` (printed last?)
    //
    // Hmm, in reverse display:
    //  `.` at top, then d's subtree, then a's subtree.
    //  d is the first child of . to appear → but shown as `├─┬`.
    //  a is the last child of . to appear → shown as `└─┬`.
    //
    //  So in reverse, `└` is for LAST child of parent. `├` for middle. No `┌`.
    //  For single child: `└` (since it's also last).
    //
    //  And d's merger has children (big.bin). big.bin is `└──` (only child of d, so also last of d's children).
    //
    //  In default mode:
    //  c is `┌──` (first child of b).
    //  f2.txt is `├──` (next child of b).
    //  b is `┌─┴` (first child of a).
    //  f1.txt is `├──` (next child of a).
    //  a is `┌─┴` (first child of .).
    //  big.bin is `┌──` (only child of d).
    //  d is `├─┴` (second child of . printed).
    //  . is `┌─┴` (only root).
    //  
    //  So in default: `┌` for first child of parent, `├` for others.
    //  In reverse: `└` for last child of parent, `├` for others.

    // Implementation: for each parent, track its printed children in print order.
    // Default: first printed = first child = `┌`/`┌─┴`. Others = `├`/`├─┴`.
    // Reverse: last printed = last child = `└`/`└─┬`? Hmm for mergers, last (bottom) or first (top)?
    // Looking: `d` (printed first of .'s children in reverse) = `├─┬`.
    //          `a` (printed last in reverse) = `└─┬`.
    //          `.` (first, root) = `└─┬`.
    // . has no siblings so it's "last" of its row-level. So `└`.
    // d is first of .'s children → `├`. a is last → `└`.
    // big.bin is only/last child of d → `└──`.
    //
    // So in reverse: last printed = `└`. First/middle = `├`.
    // In default: first printed = `┌`. Middle/last = `├`.

    // Count children per parent, and index each row within its parent's printed order
    let mut per_parent_count: std::collections::HashMap<Option<usize>, usize> = std::collections::HashMap::new();
    let mut my_order: Vec<usize> = vec![0; n];
    let mut my_total: Vec<usize> = vec![0; n];
    for i in 0..n {
        let key = rows[i].parent_row;
        let count = per_parent_count.entry(key).or_insert(0);
        my_order[i] = *count;
        *count += 1;
    }
    for i in 0..n {
        let key = rows[i].parent_row;
        my_total[i] = *per_parent_count.get(&key).unwrap_or(&1);
    }
    for i in 0..n {
        let is_first_printed = my_order[i] == 0;
        let is_last_printed = my_order[i] + 1 == my_total[i];
        let is_merger = rows[i].is_dir_merger;
        let chars = if opts.reverse {
            if is_merger {
                if is_last_printed { "└─┬" } else { "├─┬" }
            } else {
                if is_last_printed { "└──" } else { "├──" }
            }
        } else {
            if is_merger {
                if is_first_printed { "┌─┴" } else { "├─┴" }
            } else {
                if is_first_printed { "┌──" } else { "├──" }
            }
        };
        rows[i].tree_chars = chars.to_string();
    }
    let _ = rows;
}

pub fn build_prefix_strings(rows: &[Row]) -> Vec<String> {
    let n = rows.len();
    let max_depth = rows.iter().map(|r| r.depth).max().unwrap_or(0);
    // occupied[i][c] = true if row i places a tree character at col c
    let mut occupied: Vec<Vec<bool>> = vec![vec![false; max_depth + 1]; n];
    for (i, r) in rows.iter().enumerate() {
        if r.depth <= max_depth { occupied[i][r.depth] = true; }
        if r.is_dir_merger && r.depth + 1 <= max_depth {
            occupied[i][r.depth + 1] = true;
        }
    }
    // For each column, find first and last occupied row indices
    let mut col_range: Vec<(usize, usize, bool)> = Vec::with_capacity(max_depth + 1);
    for c in 0..=max_depth {
        let mut first = None;
        let mut last = None;
        for i in 0..n {
            if occupied[i][c] {
                if first.is_none() { first = Some(i); }
                last = Some(i);
            }
        }
        col_range.push((first.unwrap_or(0), last.unwrap_or(0), first.is_some()));
    }

    let mut out = Vec::with_capacity(n);
    for (i, r) in rows.iter().enumerate() {
        let mut s = String::new();
        for c in 0..r.depth {
            let cr = col_range[c];
            let show_bar = cr.2 && i > cr.0 && i < cr.1 && !occupied[i][c];
            if show_bar { s.push('│'); } else { s.push(' '); }
            s.push(' ');
        }
        s.push_str(&r.tree_chars);
        s.push(' ');
        s.push_str(&r.display_name);
        out.push(s);
    }
    out
}

fn display_width(s: &str) -> usize { s.chars().count() }

pub fn print_tree(rows: Vec<Row>, opts: &DisplayOpts) {
    if rows.is_empty() { return; }
    let mut size_strs: Vec<String> = rows.iter().map(|r| format_size_for_row(r, opts)).collect();
    let size_w = size_strs.iter().map(|s| s.chars().count()).max().unwrap_or(1);
    for s in size_strs.iter_mut() {
        let sw = s.chars().count();
        if sw < size_w { *s = format!("{}{}", " ".repeat(size_w - sw), s); }
    }
    let prefix_strs = build_prefix_strings(&rows);
    let name_area_max = prefix_strs.iter().map(|s| display_width(s)).max().unwrap_or(0);

    let percent_w = 5;

    if opts.screen_reader {
        let names: Vec<String> = rows.iter().map(|r| r.name.clone()).collect();
        let max_name = names.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        let max_size = size_strs.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        let total = rows.iter().find(|r| r.depth == 0).map(|r| r.size).unwrap_or(1).max(1);
        for (i, r) in rows.iter().enumerate() {
            let pct = (r.size as f64 * 100.0 / total as f64).round() as u64;
            let pct_s = format!("{}%", pct);
            let pct_padded = format!("{:>4}", pct_s);
            let name = format!("{:<width$}", r.name, width = max_name);
            let size = format!("{:>width$}", size_strs[i], width = max_size);
            println!("{} {} {} {}", name, r.depth, size, pct_padded);
        }
        return;
    }

    if opts.no_percent_bars {
        for (i, r) in rows.iter().enumerate() {
            let _ = r;
            let prefix = &prefix_strs[i];
            println!("{} {}", size_strs[i], prefix.trim_end());
        }
        return;
    }

    let fixed = size_w + 1 + name_area_max + 1 + 1 + percent_w;
    let bar_w = opts.terminal_width.saturating_sub(fixed).max(1);
    let total = rows.iter().find(|r| r.depth == 0).map(|r| r.size).unwrap_or(1).max(1);

    // Compute bar block counts using ceil((size/total) * (bar_w - 1))
    let bar_max = (bar_w as i64 - 1).max(1) as usize;
    let bar_widths: Vec<usize> = rows.iter().map(|r| {
        let v = (r.size as f64 / total as f64 * bar_max as f64).ceil() as i64;
        v.max(1).min(bar_max as i64) as usize
    }).collect();

    // For each row, we need ancestor widths (non-root). Build ancestor chain via parent_row.
    let ancestor_widths: Vec<Vec<usize>> = rows.iter().enumerate().map(|(i, _)| {
        let mut a = Vec::new();
        let mut cur = rows[i].parent_row;
        while let Some(p) = cur {
            if rows[p].depth != 0 {
                a.push(bar_widths[p]);
            }
            cur = rows[p].parent_row;
        }
        a
    }).collect();

    for (i, r) in rows.iter().enumerate() {
        let prefix = &prefix_strs[i];
        let padded_prefix = pad_right(prefix, name_area_max);
        let own_w = bar_widths[i];
        let anc = &ancestor_widths[i];
        let mut chars: Vec<char> = vec![' '; bar_w];
        for p in 0..bar_w {
            let pos = p + 1;
            if pos <= own_w {
                chars[p] = '█';
            } else {
                let mut cnt = 0usize;
                for &w in anc { if pos <= w { cnt += 1; } }
                chars[p] = if cnt >= 2 { '▒' } else if cnt == 1 { '░' } else { ' ' };
            }
        }
        let bar: String = if opts.bars_on_right {
            chars.iter().rev().collect()
        } else {
            chars.iter().collect()
        };
        let pct = ((r.size as f64 / total as f64) * 100.0).round() as u64;
        let pct_s = format!("{:>3}%", pct);
        println!("{} {}│{}│ {}", size_strs[i], padded_prefix, bar, pct_s);
    }
}

fn pad_right(s: &str, width: usize) -> String {
    let cw = display_width(s);
    if cw >= width { s.to_string() } else { format!("{}{}", s, " ".repeat(width - cw)) }
}

fn format_size_for_row(r: &Row, opts: &DisplayOpts) -> String {
    if opts.filecount {
        format!("{}", r.size)
    } else {
        format_size(r.size, opts.output_format)
    }
}
