fn find_ancestors<'a>(root: &'a Node, target: &Node) -> Vec<&'a Node> {
    let mut stack: Vec<&'a Node> = Vec::new();
    fn inner<'a>(cur: &'a Node, target: *const Node, stack: &mut Vec<&'a Node>) -> bool {
        stack.push(cur);
        if (cur as *const Node) == target {
            stack.pop();
            return true;
        }
        for c in &cur.children {
            if inner(c, target, stack) { return true; }
        }
