fn walk_and_emit(
    node: &Node,
    depth: usize,
    parent_row_idx: Option<usize>,
    kept: &std::collections::HashSet<*const Node>,
    opts: &DisplayOpts,
    _is_root: bool,
    out: &mut Vec<Row>,
