pub fn build_prefix_strings(rows: &[Row]) -> Vec<String> {
    let n = rows.len();
    let max_depth = rows.iter().map(|r| r.depth).max().unwrap_or(0);
    let mut occupied: Vec<Vec<bool>> = vec![vec![false; max_depth + 1]; n];
    for (i, r) in rows.iter().enumerate() {
        if r.depth <= max_depth { occupied[i][r.depth] = true; }
        if r.is_dir_merger && r.depth + 1 <= max_depth {
            occupied[i][r.depth + 1] = true;
        }
    }
    let mut col_range: Vec<(usize, usize, bool)> = Vec::with_capacity(max_depth + 1);
    for c in 0..=max_depth {
        let mut first = None;
        let mut last = None;
        for i in 0..n {
            if occupied[i][c] {
                if first.is_none() { first = Some(i); }
                last = Some(i);
            }
        }
        col_range.push((first.unwrap_or(0), last.unwrap_or(0), first.is_some()));
    }
    let mut out = Vec::with_capacity(n);
    for (i, r) in rows.iter().enumerate() {
        let mut s = String::new();
        for c in 0..r.depth {
            let cr = col_range[c];
            let show_bar = cr.2 && i > cr.0 && i < cr.1 && !occupied[i][c];
            if show_bar { s.push('│'); } else { s.push(' '); }
