fn select_top_n(root: &Node, max_rows: usize) -> std::collections::HashSet<*const Node> {
    use std::collections::HashSet;
    let mut kept: HashSet<*const Node> = HashSet::new();
    kept.insert(root as *const Node);
    let mut all: Vec<(u64, *const Node)> = Vec::new();
    collect_descendants(root, &mut all);
    all.sort_by(|a, b| b.0.cmp(&a.0));
    let limit = max_rows;
    for (_, n) in &all {
        if kept.len() >= limit { break; }
        let node_ref = unsafe { &**n };
        let ancestors = find_ancestors(root, node_ref);
        let mut all_kept = true;
        for a in &ancestors {
            if !kept.contains(&(*a as *const Node)) { all_kept = false; break; }
        }
        if all_kept { kept.insert(*n); }
    }
    kept
}

fn find_ancestors<'a>(root: &'a Node, target: &Node) -> Vec<&'a Node> {
    let mut stack: Vec<&'a Node> = Vec::new();
    fn inner<'a>(cur: &'a Node, target: *const Node, stack: &mut Vec<&'a Node>) -> bool {
        stack.push(cur);
        if (cur as *const Node) == target {
            stack.pop();
            return true;
        }
        for c in &cur.children {
            if inner(c, target, stack) { return true; }
        }
        stack.pop();
        false
    }
    inner(root, target as *const Node, &mut stack);
    stack
}

fn collect_descendants<'a>(cur: &'a Node, out: &mut Vec<(u64, *const Node)>) {
    for c in &cur.children {
        out.push((c.size, c as *const Node));
        collect_descendants(c, out);
    }
}

fn walk_and_emit(
    node: &Node,
    depth: usize,
    parent_row_idx: Option<usize>,
    kept: &std::collections::HashSet<*const Node>,
    opts: &DisplayOpts,
    _is_root: bool,
    out: &mut Vec<Row>,
) {
    let mut kept_children: Vec<&Node> = node.children.iter()
        .filter(|c| kept.contains(&(*c as *const Node)))
        .collect();
    // Default (non-reverse): sort ascending, ties alphabetical ascending.
    // Reverse: the whole output is reversed, so we compute in default order and reverse at end.
    kept_children.sort_by(|a, b| a.size.cmp(&b.size).then_with(|| a.name.cmp(&b.name)));
    let has_children = !kept_children.is_empty();

    for c in kept_children.iter() {
        walk_and_emit(c, depth + 1, None, kept, opts, false, out);
    }
    let idx = out.len();
    out.push(Row {
        size: node.size,
        name: node.name.clone(),
        display_name: display_name_for(node, opts, depth),
        depth,
        tree_chars: String::new(),
        is_dir_merger: has_children,
        full_path: node.full_path.clone(),
        parent_row: parent_row_idx,
    });
    // Assign parent_row to emitted children
    let mut i = idx;
    while i > 0 {
        i -= 1;
        if out[i].depth <= depth { break; }
        if out[i].depth == depth + 1 && out[i].parent_row.is_none() {
            out[i].parent_row = Some(idx);
        }
    }
}

