        for c in &n.children { s += count_files(c); }
        s
    }
}

fn should_include_child(n: &Node, opts: &WalkOptions) -> bool {
    if let Some(ms) = opts.min_size {
        if !opts.filecount && !n.is_dir && n.size < ms { return false; }
    }
    if opts.only_dir && !n.is_dir { return false; }
    if !opts.filter.is_empty() && !n.is_dir {
        if !matches_any(&n.full_path, &opts.filter) { return false; }
    }
    if !opts.invert_filter.is_empty() && !n.is_dir {
        if matches_any(&n.full_path, &opts.invert_filter) { return false; }
    }
    true
}

fn dir_total_size(path: &Path, opts: &WalkOptions, root_dev: Option<u64>) -> u64 {
    let mut total = 0u64;
    let meta = if opts.dereference_links { fs::metadata(path) } else { fs::symlink_metadata(path) };
    if let Ok(m) = meta {
        if opts.limit_filesystem {
            if let Some(rd) = root_dev { if m.dev() != rd { return 0; } }
        }
        let self_size = if opts.apparent_size { m.len() } else { m.blocks() * 512 };
        total += self_size;
        if m.file_type().is_dir() {
            if let Ok(rd) = fs::read_dir(path) {
                for e in rd.flatten() {
                    let p = e.path();
                    let cname = e.file_name().to_string_lossy().to_string();
                    if opts.should_ignore_name(&cname) { continue; }
                    total += dir_total_size(&p, opts, root_dev);
                }
            }
        }
    }
    total
}

pub fn build_forest(paths: &[String], opts: &WalkOptions) -> (Vec<Node>, Vec<String>) {
    let mut nodes = Vec::new();
    let mut errors = Vec::new();
    for p in paths {
        let pb = PathBuf::from(p);
        let md = if opts.dereference_links { fs::metadata(&pb) } else { fs::symlink_metadata(&pb) };
        if md.is_err() {
            errors.push(p.clone());
            continue;
        }
        let root_dev = if opts.limit_filesystem { md.as_ref().ok().map(|m| m.dev()) } else { None };
        // display for root is the user-supplied path as-is
        let display = p.clone();
        let n = walk_path(&pb, opts, root_dev, 0, &display);
        nodes.push(n);
    }
    (nodes, errors)
}
