fn select_top_n(root: &Node, max_rows: usize) -> std::collections::HashSet<*const Node> {
    use std::collections::HashSet;
    let mut kept: HashSet<*const Node> = HashSet::new();
    kept.insert(root as *const Node);
    let mut all: Vec<(u64, *const Node)> = Vec::new();
    collect_descendants(root, &mut all);
    all.sort_by(|a, b| b.0.cmp(&a.0));
    let limit = max_rows;
    for (_, n) in &all {
        if kept.len() >= limit { break; }
        let node_ref = unsafe { &**n };
        let ancestors = find_ancestors(root, node_ref);
        let mut all_kept = true;
        for a in &ancestors {
            if !kept.contains(&(*a as *const Node)) { all_kept = false; break; }
        }
        if all_kept { kept.insert(*n); }
    }
    kept
}

fn find_ancestors<'a>(root: &'a Node, target: &Node) -> Vec<&'a Node> {
    let mut stack: Vec<&'a Node> = Vec::new();
    fn inner<'a>(cur: &'a Node, target: *const Node, stack: &mut Vec<&'a Node>) -> bool {
        stack.push(cur);
        if (cur as *const Node) == target {
            stack.pop();
            return true;
        }
        for c in &cur.children {
            if inner(c, target, stack) { return true; }
        }
        stack.pop();
        false
    }
    inner(root, target as *const Node, &mut stack);
    stack
}

fn collect_descendants<'a>(cur: &'a Node, out: &mut Vec<(u64, *const Node)>) {
    for c in &cur.children {
        out.push((c.size, c as *const Node));
        collect_descendants(c, out);
    }
}

fn walk_and_emit(
    node: &Node,
    depth: usize,
    parent_row_idx: Option<usize>,
    kept: &std::collections::HashSet<*const Node>,
    opts: &DisplayOpts,
    out: &mut Vec<Row>,
) {
    let mut kept_children: Vec<&Node> = node.children.iter()
        .filter(|c| kept.contains(&(*c as *const Node)))
        .collect();
    kept_children.sort_by(|a, b| a.size.cmp(&b.size).then_with(|| a.name.cmp(&b.name)));
    let has_children = !kept_children.is_empty();

    for c in kept_children.iter() {
        walk_and_emit(c, depth + 1, None, kept, opts, out);
    }
    let idx = out.len();
    out.push(Row {
        size: node.size,
        name: node.name.clone(),
        display_name: display_name_for(node, opts, depth),
        depth,
        tree_chars: String::new(),
        is_dir_merger: has_children,
        full_path: node.full_path.clone(),
        parent_row: parent_row_idx,
    });
    let mut i = idx;
    while i > 0 {
        i -= 1;
        if out[i].depth <= depth { break; }
        if out[i].depth == depth + 1 && out[i].parent_row.is_none() {
            out[i].parent_row = Some(idx);
        }
    }
}

fn display_name_for(n: &Node, opts: &DisplayOpts, depth: usize) -> String {
    if opts.full_paths {
        n.full_path.clone()
    } else if depth == 0 {
        n.full_path.clone()
    } else {
        n.name.clone()
    }
}

fn assign_tree_chars(rows: &mut Vec<Row>, opts: &DisplayOpts) {
    let n = rows.len();
    let mut per_parent_count: std::collections::HashMap<Option<usize>, usize> = std::collections::HashMap::new();
    let mut my_order: Vec<usize> = vec![0; n];
    let mut my_total: Vec<usize> = vec![0; n];
    for i in 0..n {
        let key = rows[i].parent_row;
        let count = per_parent_count.entry(key).or_insert(0);
        my_order[i] = *count;
        *count += 1;
    }
    for i in 0..n {
        let key = rows[i].parent_row;
        my_total[i] = *per_parent_count.get(&key).unwrap_or(&1);
    }
    for i in 0..n {
        let is_first_printed = my_order[i] == 0;
        let is_last_printed = my_order[i] + 1 == my_total[i];
        let is_merger = rows[i].is_dir_merger;
        let chars = if opts.reverse {
            if is_merger {
                if is_last_printed { "└─┬" } else { "├─┬" }
            } else {
                if is_last_printed { "└──" } else { "├──" }
            }
        } else {
            if is_merger {
                if is_first_printed { "┌─┴" } else { "├─┴" }
            } else {
                if is_first_printed { "┌──" } else { "├──" }
            }
        };
        rows[i].tree_chars = chars.to_string();
    }
}

// Per row per col: does this row have an UP or DOWN extension at col?
fn col_extensions(rows: &[Row], max_depth: usize, opts: &DisplayOpts) -> (Vec<Vec<bool>>, Vec<Vec<bool>>, Vec<Vec<bool>>) {
    let n = rows.len();
    let mut has_up: Vec<Vec<bool>> = vec![vec![false; max_depth + 1]; n];
    let mut has_down: Vec<Vec<bool>> = vec![vec![false; max_depth + 1]; n];
    let mut occupied: Vec<Vec<bool>> = vec![vec![false; max_depth + 1]; n];
    for (i, r) in rows.iter().enumerate() {
        let own_col = r.depth;
        let merger_col = r.depth + 1;
        let is_merger = r.is_dir_merger;
        // Determine tree chars: first char at own_col, third char at merger_col (if merger).
        let c0 = r.tree_chars.chars().next().unwrap_or(' ');
        if own_col <= max_depth {
            occupied[i][own_col] = true;
            // In default: ┌=DOWN, ├=UP+DOWN, └=UP (shouldn't appear in default non-reverse)
            // In reverse: └=UP, ├=UP+DOWN, ┌=DOWN (shouldn't appear in reverse)
            match c0 {
                '┌' => { has_down[i][own_col] = true; }
                '├' => { has_up[i][own_col] = true; has_down[i][own_col] = true; }
                '└' => { has_up[i][own_col] = true; }
                _ => {}
            }
        }
        if is_merger && merger_col <= max_depth {
            occupied[i][merger_col] = true;
            if opts.reverse {
                // `┬` at merger_col: DOWN
                has_down[i][merger_col] = true;
            } else {
                // `┴` at merger_col: UP
                has_up[i][merger_col] = true;
            }
        }
    }
    (has_up, has_down, occupied)
}

pub fn build_prefix_strings(rows: &[Row], opts: &DisplayOpts) -> Vec<String> {
    let n = rows.len();
    let max_depth = rows.iter().map(|r| r.depth).max().unwrap_or(0);
    let (has_up, has_down, occupied) = col_extensions(rows, max_depth, opts);
    // For each col, compute segments: pairs of (start_row, end_row)
    // Segments are contiguous runs. Rows with has_up AND has_down continue the segment.
    let mut segments: Vec<Vec<(usize, usize)>> = vec![Vec::new(); max_depth + 1];
    for c in 0..=max_depth {
        let mut start: Option<usize> = None;
        for i in 0..n {
            let u = has_up[i][c];
            let d = has_down[i][c];
            if u {
                if let Some(s) = start {
                    segments[c].push((s, i));
                    start = None;
                }
            }
            if d {
                start = Some(i);
            }
        }
        // discard unclosed
    }
    let mut out = Vec::with_capacity(n);
    for (i, r) in rows.iter().enumerate() {
        let mut s = String::new();
        for c in 0..r.depth {
            let show_bar = !occupied[i][c] && segments[c].iter().any(|&(a, b)| i > a && i < b);
            if show_bar { s.push('│'); } else { s.push(' '); }
            s.push(' ');
        }
        s.push_str(&r.tree_chars);
        s.push(' ');
        s.push_str(&r.display_name);
        out.push(s);
    }
    out
}

fn display_width(s: &str) -> usize { s.chars().count() }

pub fn print_tree(result: FlattenResult, opts: &DisplayOpts) {
    let rows = result.rows;
    if rows.is_empty() { return; }
    let total = if opts.skip_total { result.total.max(1) } else {
        rows.iter().find(|r| r.depth == 0).map(|r| r.size).unwrap_or(result.total).max(1)
    };

    let mut size_strs: Vec<String> = rows.iter().map(|r| format_size_for_row(r, opts)).collect();
    let size_w = size_strs.iter().map(|s| s.chars().count()).max().unwrap_or(1);
    for s in size_strs.iter_mut() {
        let sw = s.chars().count();
        if sw < size_w { *s = format!("{}{}", " ".repeat(size_w - sw), s); }
    }
    let prefix_strs = build_prefix_strings(&rows, opts);
    let name_area_max = prefix_strs.iter().map(|s| display_width(s)).max().unwrap_or(0);

    if opts.screen_reader {
        let names: Vec<String> = rows.iter().map(|r| r.name.clone()).collect();
        let max_name = names.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        let max_size = size_strs.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        for (i, r) in rows.iter().enumerate() {
            let pct = (r.size as f64 * 100.0 / total as f64).round() as u64;
            let pct_s = format!("{}%", pct);
            let pct_padded = format!("{:>4}", pct_s);
            let name = format!("{:<width$}", r.name, width = max_name);
            let size = format!("{:>width$}", size_strs[i], width = max_size);
            println!("{} {} {} {}", name, r.depth, size, pct_padded);
        }
        return;
    }

    if opts.no_percent_bars {
        for (i, _r) in rows.iter().enumerate() {
            let prefix = &prefix_strs[i];
            println!("{} {}", size_strs[i], prefix.trim_end());
        }
        return;
    }

    let percent_w = 5;
    let fixed = size_w + 1 + name_area_max + 1 + 1 + percent_w;
    let bar_w = opts.terminal_width.saturating_sub(fixed).max(1);

    let bar_max = bar_w.saturating_sub(1).max(1);
    let bar_widths: Vec<usize> = rows.iter().map(|r| {
        let v = (r.size as f64 / total as f64 * bar_max as f64).ceil() as i64;
        v.max(1).min(bar_max as i64) as usize
    }).collect();

    let ancestor_widths: Vec<Vec<usize>> = rows.iter().enumerate().map(|(i, _)| {
        let mut a = Vec::new();
        let mut cur = rows[i].parent_row;
        while let Some(p) = cur {
            if rows[p].depth != 0 {
                a.push(bar_widths[p]);
            }
            cur = rows[p].parent_row;
        }
        a
    }).collect();

    for (i, r) in rows.iter().enumerate() {
        let prefix = &prefix_strs[i];
        let padded_prefix = pad_right(prefix, name_area_max);
        let own_w = bar_widths[i];
        let anc = &ancestor_widths[i];
        let mut chars: Vec<char> = vec![' '; bar_w];
        for p in 0..bar_w {
            let pos = p + 1;
            if pos <= own_w {
                chars[p] = '█';
            } else {
                let mut cnt = 0usize;
                for &w in anc { if pos <= w { cnt += 1; } }
                chars[p] = if cnt >= 2 { '▒' } else if cnt == 1 { '░' } else { ' ' };
            }
        }
        let bar: String = if opts.bars_on_right {
            let fill_len = chars.iter().rposition(|&c| c != ' ').map(|p| p + 1).unwrap_or(0);
            let fill: String = chars[..fill_len].iter().rev().collect();
            let left_pad = bar_w.saturating_sub(fill_len).saturating_sub(1);
            let mut s = String::new();
            for _ in 0..left_pad { s.push(' '); }
            s.push_str(&fill);
            s.push(' ');
            s
        } else {
            chars.iter().collect()
        };
        let pct = ((r.size as f64 / total as f64) * 100.0).round() as u64;
        let pct_s = format!("{:>3}%", pct);
        println!("{} {}│{}│ {}", size_strs[i], padded_prefix, bar, pct_s);
    }
}

fn pad_right(s: &str, width: usize) -> String {
    let cw = display_width(s);
    if cw >= width { s.to_string() } else { format!("{}{}", s, " ".repeat(width - cw)) }
}

fn format_size_for_row(r: &Row, opts: &DisplayOpts) -> String {
    if opts.filecount {
        format!("{}", r.size)
    } else {
        format_size(r.size, opts.output_format)
    }
}
