}

fn tty_size() -> Option<(usize, usize)> {
    use std::os::unix::io::AsRawFd;
    #[repr(C)]
    struct Winsize { ws_row: u16, ws_col: u16, _x: u16, _y: u16 }
    extern "C" { fn ioctl(fd: i32, req: u64, ...) -> i32; }
    let fd = std::io::stdout().as_raw_fd();
    let mut ws = Winsize { ws_row: 0, ws_col: 0, _x: 0, _y: 0 };
    let r = unsafe { ioctl(fd, 0x5413, &mut ws) };
    if r == 0 && ws.ws_col > 0 { Some((ws.ws_col as usize, ws.ws_row as usize)) } else { None }
}

pub fn to_display_tree(nodes: Vec<Node>) -> Node {
    if nodes.len() == 1 {
        return nodes.into_iter().next().unwrap();
    }
    let total: u64 = nodes.iter().map(|n| n.size).sum();
    Node {
        name: "(total)".to_string(),
        full_path: "(total)".to_string(),
        size: total,
        is_dir: true,
        children: nodes,
        errored: false,
    }
}

#[derive(Clone)]
pub struct Row {
    pub size: u64,
    pub name: String,
    pub display_name: String,
    pub depth: usize,
    pub tree_chars: String,
    pub is_dir_merger: bool,
    pub full_path: String,
    pub parent_row: Option<usize>,
}

pub struct FlattenResult {
    pub rows: Vec<Row>,
    pub total: u64,
}

pub fn flatten_tree(root_in: &Node, opts: &DisplayOpts, max_rows: usize) -> FlattenResult {
    let root_owned: Node;
    let root = if opts.only_file {
        root_owned = flatten_only_files(root_in);
        &root_owned
    } else {
        root_in
    };

    let total = root.size;
    let kept = select_top_n(root, max_rows);
    let mut rows: Vec<Row> = Vec::new();
    walk_and_emit(root, 0, None, &kept, opts, &mut rows);

    // Apply reverse by flipping rows and remapping parent_row
    if opts.reverse {
        let n = rows.len();
        let remap: Vec<usize> = (0..n).map(|i| n - 1 - i).collect();
        let mut flipped: Vec<Row> = Vec::with_capacity(n);
        for i in 0..n {
            let orig = &rows[n - 1 - i];
            let mut r = orig.clone();
            r.parent_row = orig.parent_row.map(|p| remap[p]);
            flipped.push(r);
        }
        rows = flipped;
    }

    assign_tree_chars(&mut rows, opts);

    if opts.skip_total && !rows.is_empty() {
        // Drop root row and shift depths
        let root_idx = rows.iter().position(|r| r.depth == 0);
        if let Some(ri) = root_idx {
            let mut kept_rows: Vec<Row> = Vec::new();
            let mut id_map: std::collections::HashMap<usize, usize> = std::collections::HashMap::new();
            for (i, r) in rows.iter().enumerate() {
                if i == ri { continue; }
                id_map.insert(i, kept_rows.len());
                let mut nr = r.clone();
                nr.depth = r.depth.saturating_sub(1);
                kept_rows.push(nr);
            }
            for kr in kept_rows.iter_mut() {
                if let Some(p) = kr.parent_row {
                    kr.parent_row = id_map.get(&p).copied();
                }
            }
            rows = kept_rows;
            assign_tree_chars(&mut rows, opts);
        }
    }

    FlattenResult { rows, total }
}

fn flatten_only_files(root: &Node) -> Node {
    fn is_leaf(n: &Node) -> bool { !n.is_dir || n.children.is_empty() }
    fn collect_leaves(node: &Node, out: &mut Vec<Node>) {
        for c in &node.children {
            if is_leaf(c) {
                out.push(clone_leaf(c));
            } else {
                collect_leaves(c, out);
            }
        }
    }
    fn clone_leaf(n: &Node) -> Node {
        Node {
            name: n.name.clone(),
            full_path: n.full_path.clone(),
            size: n.size,
            is_dir: n.is_dir,
            children: vec![],
            errored: n.errored,
        }
    }
    let mut leaves = Vec::new();
    collect_leaves(root, &mut leaves);
    Node {
        name: root.name.clone(),
        full_path: root.full_path.clone(),
        size: root.size,
        is_dir: true,
        children: leaves,
        errored: root.errored,
    }
}

