cat > /workspace/src/walk.rs <<'EOF'
use std::fs;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

pub struct Node {
    pub name: String,
    pub full_path: String,
    pub size: u64,
    pub is_dir: bool,
    pub children: Vec<Node>,
    pub errored: bool,
}

pub struct WalkOptions {
    pub apparent_size: bool,
    pub dereference_links: bool,
    pub limit_filesystem: bool,
    pub ignore_hidden: bool,
    pub ignore_dirs: Vec<String>,
    pub filter: Vec<String>,
    pub invert_filter: Vec<String>,
    pub filecount: bool,
    pub min_size: Option<u64>,
    pub only_dir: bool,
    pub only_file: bool,
    pub full_paths: bool,
    pub max_depth: Option<u64>,
    pub collapse: Vec<String>,
}

impl WalkOptions {
    pub fn should_ignore_name(&self, name: &str) -> bool {
        if self.ignore_hidden && name.starts_with('.') && name != "." && name != ".." {
            return true;
        }
        false
    }
    pub fn is_collapsed(&self, name: &str) -> bool {
        self.collapse.iter().any(|c| c == name)
    }
    pub fn path_matches_ignore(&self, full_path: &str) -> bool {
        let norm = normalize_path(full_path);
        for d in &self.ignore_dirs {
            let dn = normalize_path(d);
            if norm == dn { return true; }
        }
        false
    }
}

fn normalize_path(p: &str) -> String {
    let mut s = p.to_string();
    while s.starts_with("./") { s = s[2..].to_string(); }
    while s.ends_with('/') && s.len() > 1 { s.pop(); }
    s
}

fn matches_any(path: &str, pats: &[String]) -> bool {
    for p in pats {
        if crate::rx::simple_regex_search(p, path) { return true; }
    }
    false
}

pub fn walk_path(path: &Path, opts: &WalkOptions, root_dev: Option<u64>, depth: u64, display_path: &str) -> Node {
    let meta = if opts.dereference_links {
        fs::metadata(path)
    } else {
        fs::symlink_metadata(path)
    };
    let name = path.file_name().map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| display_path.to_string());
    match meta {
        Ok(m) => {
            if opts.limit_filesystem {
                if let Some(rd) = root_dev {
                    if m.dev() != rd {
                        return Node { name, full_path: display_path.to_string(), size: 0, is_dir: false, children: vec![], errored: false };
                    }
                }
            }
            let is_symlink = m.file_type().is_symlink();
            let is_dir = if opts.dereference_links { m.is_dir() } else {
                m.file_type().is_dir() && !is_symlink
            };
            if is_dir && (opts.max_depth.map(|d| depth < d).unwrap_or(true)) && !opts.is_collapsed(&name) {
                let mut children = Vec::new();
                let mut size_bytes: u64 = if opts.filecount { 0 } else {
                    if opts.apparent_size { m.len() } else { m.blocks() * 512 }
                };
                let mut filec: u64 = 0;
                match fs::read_dir(path) {
                    Ok(rd) => {
                        let mut entries: Vec<(PathBuf, String)> = Vec::new();
                        for e in rd.flatten() {
                            let ep = e.path();
                            let cname = e.file_name().to_string_lossy().to_string();
                            if opts.should_ignore_name(&cname) { continue; }
                            entries.push((ep, cname));
                        }
                        entries.sort_by(|a, b| a.1.cmp(&b.1));
                        for (ep, cname) in entries {
                            let cdisplay = if opts.full_paths {
                                ep.to_string_lossy().to_string()
                            } else {
                                let base = display_path.trim_end_matches('/');
                                format!("{}/{}", base, cname)
                            };
                            if opts.path_matches_ignore(&cdisplay) { continue; }
                            let ch = walk_path(&ep, opts, root_dev, depth + 1, &cdisplay);
                            size_bytes = size_bytes.saturating_add(ch.size);
                            filec += count_files(&ch);
                            children.push(ch);
                        }
                    }
                    Err(_) => {
                        return Node { name, full_path: display_path.to_string(), size: 0, is_dir: true, children: vec![], errored: true };
                    }
                }
                if opts.filecount {
                    return Node { name, full_path: display_path.to_string(), size: filec, is_dir: true, children, errored: false };
                }
                return Node { name, full_path: display_path.to_string(), size: size_bytes, is_dir: true, children, errored: false };
            } else {
                let size = if is_dir {
                    dir_total_size(path, opts, root_dev)
                } else if opts.filecount {
                    1
                } else {
                    if opts.apparent_size { m.len() } else { m.blocks() * 512 }
                };
                Node { name, full_path: display_path.to_string(), size, is_dir, children: vec![], errored: false }
            }
        }
        Err(_) => {
            Node { name, full_path: display_path.to_string(), size: 0, is_dir: false, children: vec![], errored: true }
        }
    }
}

fn count_files(n: &Node) -> u64 {
    if !n.is_dir { 1 } else {
        let mut s = 0u64;
        for c in &n.children { s += count_files(c); }
        s
    }
}

fn dir_total_size(path: &Path, opts: &WalkOptions, root_dev: Option<u64>) -> u64 {
    let mut total = 0u64;
    let meta = if opts.dereference_links { fs::metadata(path) } else { fs::symlink_metadata(path) };
    if let Ok(m) = meta {
        if opts.limit_filesystem {
            if let Some(rd) = root_dev { if m.dev() != rd { return 0; } }
        }
        let self_size = if opts.apparent_size { m.len() } else { m.blocks() * 512 };
        total += self_size;
        if m.file_type().is_dir() {
            if let Ok(rd) = fs::read_dir(path) {
                for e in rd.flatten() {
                    let p = e.path();
                    let cname = e.file_name().to_string_lossy().to_string();
                    if opts.should_ignore_name(&cname) { continue; }
                    total += dir_total_size(&p, opts, root_dev);
                }
            }
        }
    }
    total
}

pub fn build_forest(paths: &[String], opts: &WalkOptions) -> (Vec<Node>, Vec<String>) {
    let mut nodes = Vec::new();
    let mut errors = Vec::new();
