                    if opts.apparent_size { m.len() } else { m.blocks() * 512 }
                };
                let mut filec: u64 = 0;
                match fs::read_dir(path) {
                    Ok(rd) => {
                        let mut entries: Vec<(PathBuf, String)> = Vec::new();
                        for e in rd.flatten() {
                            let ep = e.path();
                            let cname = e.file_name().to_string_lossy().to_string();
                            if opts.should_ignore_name(&cname) { continue; }
                            entries.push((ep, cname));
                        }
                        entries.sort_by(|a, b| a.1.cmp(&b.1));
                        for (ep, cname) in entries {
                            let cdisplay = if opts.full_paths {
                                ep.to_string_lossy().to_string()
                            } else {
                                let base = display_path.trim_end_matches('/');
                                format!("{}/{}", base, cname)
                            };
                            if opts.path_matches_ignore(&cdisplay) { continue; }
                            let ch = walk_path(&ep, opts, root_dev, depth + 1, &cdisplay);
                            size_bytes = size_bytes.saturating_add(ch.size);
                            filec += count_files(&ch);
                            children.push(ch);
                        }
                    }
                    Err(_) => {
                        return Node { name, full_path: display_path.to_string(), size: 0, is_dir: true, children: vec![], errored: true };
                    }
                }
                if opts.filecount {
                    return Node { name, full_path: display_path.to_string(), size: filec, is_dir: true, children, errored: false };
                }
                return Node { name, full_path: display_path.to_string(), size: size_bytes, is_dir: true, children, errored: false };
            } else {
                let size = if is_dir {
                    dir_total_size(path, opts, root_dev)
                } else if opts.filecount {
                    1
                } else {
                    if opts.apparent_size { m.len() } else { m.blocks() * 512 }
                };
                Node { name, full_path: display_path.to_string(), size, is_dir, children: vec![], errored: false }
            }
        }
        Err(_) => {
            Node { name, full_path: display_path.to_string(), size: 0, is_dir: false, children: vec![], errored: true }
        }
    }
}

fn count_files(n: &Node) -> u64 {
    if !n.is_dir { 1 } else {
        let mut s = 0u64;
        for c in &n.children { s += count_files(c); }
        s
    }
}

fn dir_total_size(path: &Path, opts: &WalkOptions, root_dev: Option<u64>) -> u64 {
    let mut total = 0u64;
    let meta = if opts.dereference_links { fs::metadata(path) } else { fs::symlink_metadata(path) };
    if let Ok(m) = meta {
        if opts.limit_filesystem {
            if let Some(rd) = root_dev { if m.dev() != rd { return 0; } }
        }
        let self_size = if opts.apparent_size { m.len() } else { m.blocks() * 512 };
        total += self_size;
        if m.file_type().is_dir() {
            if let Ok(rd) = fs::read_dir(path) {
                for e in rd.flatten() {
                    let p = e.path();
                    let cname = e.file_name().to_string_lossy().to_string();
                    if opts.should_ignore_name(&cname) { continue; }
                    total += dir_total_size(&p, opts, root_dev);
                }
            }
        }
    }
    total
}

pub fn build_forest(paths: &[String], opts: &WalkOptions) -> (Vec<Node>, Vec<String>) {
    let mut nodes = Vec::new();
    let mut errors = Vec::new();
    for p in paths {
        let pb = PathBuf::from(p);
        let md = if opts.dereference_links { fs::metadata(&pb) } else { fs::symlink_metadata(&pb) };
        if md.is_err() {
            errors.push(p.clone());
            continue;
        }
        let root_dev = if opts.limit_filesystem { md.as_ref().ok().map(|m| m.dev()) } else { None };
        let display = p.clone();
        let n = walk_path(&pb, opts, root_dev, 0, &display);
        nodes.push(n);
    }
    (nodes, errors)
}

// Apply regex filters (-e, -v): recomputes the tree by keeping only matching files
// and their ancestors, with sizes recomputed.
pub fn apply_regex_filters(n: Node, opts: &WalkOptions) -> Option<Node> {
    if opts.filter.is_empty() && opts.invert_filter.is_empty() {
        return Some(n);
    }
    apply_filters_inner(n, opts)
}

fn apply_filters_inner(mut n: Node, opts: &WalkOptions) -> Option<Node> {
    if !n.is_dir {
        // It's a file - check filter
        if !opts.filter.is_empty() && !matches_any(&n.full_path, &opts.filter) {
            return None;
        }
        if !opts.invert_filter.is_empty() && matches_any(&n.full_path, &opts.invert_filter) {
            return None;
        }
        return Some(n);
    }
    // Recurse into children
    let mut new_children: Vec<Node> = Vec::new();
    for c in n.children.into_iter() {
        if let Some(kept) = apply_filters_inner(c, opts) {
            new_children.push(kept);
        }
    }
    if new_children.is_empty() {
        // No matching descendants
        return None;
    }
    // Recompute size from children + dir inode size
    let mut new_size: u64 = 0;
    if !opts.filecount {
        // Get the dir's own size from the original metadata (we lost it). Approximate by computing.
        let path = std::path::Path::new(&n.full_path);
        if let Ok(m) = fs::symlink_metadata(path) {
            new_size += if opts.apparent_size { m.len() } else { m.blocks() * 512 };
        }
    }
    for c in &new_children {
        new_size += c.size;
    }
    n.children = new_children;
    n.size = new_size;
    Some(n)
}
